import type {
  CommandDefinition,
  MatchingOutputSchemas,
  OperationInputSchemas,
  QueryDefinition,
  QueryFunctions,
  ServiceDefinition,
  ServiceId,
  ServiceState,
} from './types.ts';

type InvalidInternalOperationName<TName extends string> = {
  __internal_naming_error: `Operation "${TName}" has internal: true but must be prefixed with "_"`;
};

type InvalidUnderscoreWithoutInternal<TName extends string> = {
  __internal_naming_error: `Operation "${TName}" is prefixed with "_" and must set internal: true`;
};

type InternalOperationNaming<TKey> = TKey extends string
  ? TKey extends `_${string}`
    ? { internal: true } | InvalidUnderscoreWithoutInternal<TKey>
    : { internal?: false } | InvalidInternalOperationName<TKey>
  : {};

/**
 * Authoring-side query map derived from separate query input/output schema maps.
 *
 * The second mapped-type intersection is deliberate. During experiments, TypeScript would infer
 * the `input` schema for each inline query, but then lose the corresponding `output` schema before
 * it contextually typed sibling callbacks. Repeating the output map through a keyed `output` view
 * keeps each query key's input and output schemas correlated while handlers, load hooks, and
 * static callbacks are being typed.
 */
type DefinedQueries<
  TState,
  TQueryInputSchemas extends OperationInputSchemas,
  TQueryOutputSchemas extends MatchingOutputSchemas<TQueryInputSchemas>,
  TCommandInputSchemas extends OperationInputSchemas,
  TCommandOutputSchemas extends MatchingOutputSchemas<TCommandInputSchemas>,
> = {
  [TKey in keyof TQueryInputSchemas]: QueryDefinition<
    TState,
    TQueryInputSchemas[TKey],
    TQueryOutputSchemas[TKey],
    TCommandInputSchemas,
    TCommandOutputSchemas,
    QueryFunctions<TQueryInputSchemas, TQueryOutputSchemas>
  > &
    InternalOperationNaming<TKey>;
} & {
  [TKey in keyof TQueryOutputSchemas]: {
    output: TQueryOutputSchemas[TKey];
  };
};

/**
 * Authoring-side command map derived from separate command input/output schema maps.
 *
 * Commands do not need access to the command schema maps in their own context, but they still
 * benefit from the same key-correlation trick as queries so TypeScript preserves each inline
 * command object's `output` schema while typing its `handler`.
 */
type DefinedCommands<
  TState,
  TCommandInputSchemas extends OperationInputSchemas,
  TCommandOutputSchemas extends MatchingOutputSchemas<TCommandInputSchemas>,
  TQueryInputSchemas extends OperationInputSchemas,
  TQueryOutputSchemas extends MatchingOutputSchemas<TQueryInputSchemas>,
> = {
  [TKey in keyof TCommandInputSchemas]: CommandDefinition<
    TState,
    TCommandInputSchemas[TKey],
    TCommandOutputSchemas[TKey],
    TCommandInputSchemas,
    TCommandOutputSchemas,
    QueryFunctions<TQueryInputSchemas, TQueryOutputSchemas>
  > &
    InternalOperationNaming<TKey>;
} & {
  [TKey in keyof TCommandOutputSchemas]: {
    output: TCommandOutputSchemas[TKey];
  };
};

/**
 * Finalizes a service definition while preserving inline query and command inference.
 *
 * The generic order matters here. We infer the per-operation schema maps first, then derive the
 * concrete query/command definition maps from those schemas. If we instead ask TypeScript to infer
 * the full runtime `ServiceDefinition` maps directly, it widens callback parameters to `unknown`
 * before it has correlated each inline object's `input` and `output` properties.
 */
export const defineService = <
  // `extends object` rejects primitives, `null`, and `undefined` (while still accepting both
  // `interface` and `type` state shapes); `ServiceState` additionally rejects arrays. State must be a
  // plain object — see `ServiceState` for the deep-signal / deep-reconcile reasons.
  TState extends object,
  const TQueryInputSchemas extends OperationInputSchemas,
  const TQueryOutputSchemas extends MatchingOutputSchemas<TQueryInputSchemas>,
  const TCommandInputSchemas extends OperationInputSchemas,
  const TCommandOutputSchemas extends MatchingOutputSchemas<TCommandInputSchemas>,
  // `const` keeps the id a literal (e.g. `'core/docgen'`) instead of widening to `string`, so a
  // definition's id type can be reused as a key elsewhere.
  const TId extends ServiceId = ServiceId,
>(def: {
  id: TId;
  description?: string;
  internal?: boolean;
  initialState: ServiceState<TState>;
  queries: DefinedQueries<
    TState,
    TQueryInputSchemas,
    TQueryOutputSchemas,
    TCommandInputSchemas,
    TCommandOutputSchemas
  >;
  commands: DefinedCommands<
    TState,
    TCommandInputSchemas,
    TCommandOutputSchemas,
    TQueryInputSchemas,
    TQueryOutputSchemas
  >;
}): ServiceDefinition<
  TState,
  DefinedQueries<
    TState,
    TQueryInputSchemas,
    TQueryOutputSchemas,
    TCommandInputSchemas,
    TCommandOutputSchemas
  >,
  DefinedCommands<
    TState,
    TCommandInputSchemas,
    TCommandOutputSchemas,
    TQueryInputSchemas,
    TQueryOutputSchemas
  >,
  TId
> => def;

import { describe, expect, it } from 'vitest';

import { OpenServiceValidationError } from '../../server-errors.ts';
import { deserializeError, serializeError } from './service-error-serialization.ts';

describe('serializeError / deserializeError', () => {
  it('round-trips name, message, and stack', () => {
    const original = new TypeError('boom');
    const restored = deserializeError(serializeError(original));

    expect(restored).toBeInstanceOf(Error);
    expect(restored.name).toBe('TypeError');
    expect(restored.message).toBe('boom');
    expect(restored.stack).toBe(original.stack);
  });

  it('preserves the nested cause chain as real Errors', () => {
    const root = new Error('root');
    const middle = new Error('middle', { cause: root });
    const top = new Error('top', { cause: middle });

    const restored = deserializeError(serializeError(top));

    expect(restored.message).toBe('top');
    expect((restored.cause as Error).message).toBe('middle');
    expect((restored.cause as Error).cause).toBeInstanceOf(Error);
    expect(((restored.cause as Error).cause as Error).message).toBe('root');
  });

  it('preserves an aggregated array of causes (as produced by the .loaded() drain)', () => {
    const primary = new Error('primary');
    primary.cause = { aggregated: [new Error('a'), new Error('b')] };

    const restored = deserializeError(serializeError(primary));
    const aggregated = (restored.cause as { aggregated: Error[] }).aggregated;

    expect(aggregated).toHaveLength(2);
    expect(aggregated[0]).toBeInstanceOf(Error);
    expect(aggregated[0].message).toBe('a');
    expect(aggregated[1].message).toBe('b');
  });

  it('retains Storybook error fields like code and fromStorybook', () => {
    const original = new OpenServiceValidationError({
      kind: 'command',
      serviceId: 'svc',
      name: 'run',
      phase: 'input',
      issues: [{ message: 'nope' }],
    });

    const restored = deserializeError(serializeError(original)) as Error & {
      code?: number;
      fromStorybook?: boolean;
    };

    expect(restored.message).toBe(original.message);
    expect(restored.fromStorybook).toBe(true);
    expect(restored.code).toBe(5);
  });

  it('produces a transport-safe (structured-cloneable) payload', () => {
    const error = new Error('with fn');
    (error as unknown as Record<string, unknown>).callback = () => 'dropped';
    (error as unknown as Record<string, unknown>).count = 3;

    const serialized = serializeError(error);

    expect(() => structuredClone(serialized)).not.toThrow();
    expect(serialized.properties).toMatchObject({ count: 3 });
    expect(serialized.properties?.callback).toBeUndefined();
  });

  it('wraps non-Error throws in a real Error', () => {
    const restored = deserializeError(serializeError('just a string'));

    expect(restored).toBeInstanceOf(Error);
    expect(restored.message).toBe('just a string');
  });
});

/**
 * Error (de)serialization for remote command execution.
 *
 * A command invoked from a runtime that has no local handler runs on a peer; when it throws, the
 * thrown value has to cross the channel and be rethrown on the requester. `Error` instances are not
 * structured-cloneable in a way that survives a websocket (JSON) or postMessage transport with their
 * `name`, `stack`, `cause`, and Storybook-specific fields (`code`, `fromStorybook`, …) intact, so we
 * convert to and from a plain, transport-safe shape here.
 *
 * The conversion is recursive: an error's `cause` (and any nested arrays/objects, e.g. the
 * `cause.aggregated` array used by the `.loaded()` drain) is walked so a multi-cause failure arrives
 * on the requester with its chain reconstructed rather than flattened to a single message.
 */

/** Marks a serialized object as a reconstructable `Error` rather than a plain payload object. */
const ERROR_MARKER = '__openServiceError__' as const;

/** Keys handled explicitly so they are not duplicated into the extra-properties bag. */
const RESERVED_KEYS = new Set<string>([ERROR_MARKER, 'name', 'message', 'stack', 'cause']);

/** Transport-safe representation of a thrown `Error`, including its recursive `cause` chain. */
export interface SerializedError {
  [ERROR_MARKER]: true;
  name: string;
  message: string;
  stack?: string;
  /** The error's `cause`, itself serialized (another error, a plain object, an array, …). */
  cause?: unknown;
  /** Extra own enumerable fields (e.g. Storybook's `code`, `fromStorybook`), serialized. */
  properties?: Record<string, unknown>;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isSerializedError(value: unknown): value is SerializedError {
  return isPlainObject(value) && value[ERROR_MARKER] === true;
}

/**
 * Reduces any value to one a channel transport can clone.
 *
 * Functions, symbols, and `undefined` are dropped (structuredClone throws on functions/symbols);
 * `bigint` is stringified; plain objects and arrays are walked; `Error`s become {@link SerializedError}.
 */
function toTransportSafe(value: unknown): unknown {
  if (value instanceof Error) {
    return serializeError(value);
  }

  if (Array.isArray(value)) {
    return value.map((entry) => toTransportSafe(entry));
  }

  if (isPlainObject(value)) {
    const result: Record<string, unknown> = {};
    for (const [key, entry] of Object.entries(value)) {
      result[key] = toTransportSafe(entry);
    }
    return result;
  }

  if (value === null) {
    return null;
  }

  const kind = typeof value;
  if (kind === 'string' || kind === 'number' || kind === 'boolean') {
    return value;
  }
  if (kind === 'bigint') {
    return (value as bigint).toString();
  }

  // function / symbol / undefined: not cloneable and not meaningful on the wire.
  return undefined;
}

/**
 * Converts a thrown value into a transport-safe {@link SerializedError}.
 *
 * Non-`Error` throws (a string, an object, …) are wrapped in a synthetic error whose message is the
 * stringified value, so the requester always receives a real `Error` to reject with.
 */
export function serializeError(value: unknown): SerializedError {
  if (!(value instanceof Error)) {
    return { [ERROR_MARKER]: true, name: 'Error', message: String(value) };
  }

  const properties: Record<string, unknown> = {};
  for (const key of Object.keys(value)) {
    if (!RESERVED_KEYS.has(key)) {
      properties[key] = toTransportSafe((value as unknown as Record<string, unknown>)[key]);
    }
  }

  return {
    [ERROR_MARKER]: true,
    name: value.name,
    message: value.message,
    ...(value.stack !== undefined ? { stack: value.stack } : {}),
    ...(value.cause !== undefined ? { cause: toTransportSafe(value.cause) } : {}),
    ...(Object.keys(properties).length > 0 ? { properties } : {}),
  };
}

/** Inverse of {@link toTransportSafe}: rebuilds nested errors while passing other values through. */
function fromTransportSafe(value: unknown): unknown {
  if (isSerializedError(value)) {
    return deserializeError(value);
  }

  if (Array.isArray(value)) {
    return value.map((entry) => fromTransportSafe(entry));
  }

  if (isPlainObject(value)) {
    const result: Record<string, unknown> = {};
    for (const [key, entry] of Object.entries(value)) {
      result[key] = fromTransportSafe(entry);
    }
    return result;
  }

  return value;
}

/**
 * Rebuilds an `Error` from a {@link SerializedError}, restoring its `name`, `stack`, `cause` chain,
 * and any extra fields (so a Storybook error arrives with `code`/`fromStorybook` intact).
 *
 * The result is a plain `Error`, not the original subclass — reconstructing arbitrary classes across
 * a realm boundary is neither possible nor needed; callers branch on the restored fields instead.
 */
export function deserializeError(serialized: SerializedError): Error {
  // A generic Error is intentional: this reconstructs an arbitrary error thrown in another runtime
  // (its original class cannot cross the realm boundary). Storybook-specific fields like `code` and
  // `fromStorybook` are restored from `properties`, so callers can still branch on them.
  // eslint-disable-next-line local-rules/no-uncategorized-errors
  const error = new Error(serialized.message);
  error.name = serialized.name;

  if (serialized.stack !== undefined) {
    error.stack = serialized.stack;
  }
  if ('cause' in serialized) {
    error.cause = fromTransportSafe(serialized.cause);
  }
  if (serialized.properties) {
    for (const [key, value] of Object.entries(serialized.properties)) {
      (error as unknown as Record<string, unknown>)[key] = fromTransportSafe(value);
    }
  }

  return error;
}

import { afterEach, describe, expect, it } from 'vitest';

import { OpenServiceMissingChannelError } from '../../server-errors.ts';
import { mutableRecordLookupServiceDef } from './fixtures.ts';
import {
  SERVICE_PATCHES,
  SERVICE_SYNC_START_REPLY,
  SERVICE_SYNC_START,
} from './service-channel.ts';
import { clearRegistry, registerService } from './server.ts';
import { createTestChannel, installTestChannel } from '../../channels/test-channel.ts';

const { id: recordServiceId } = mutableRecordLookupServiceDef;

const createMockChannel = createTestChannel;
const installChannel = installTestChannel;

afterEach(() => {
  clearRegistry();
  installChannel(null);
});

// These tests exercise the server transport that `registerService` wires when a channel is present
// BEFORE registration — the dev server installs it in its `services` preset, so there is no separate
// connect step. The server is always a relay hub: one dev server bridges every connected manager tab.

describe('registerService: channel wiring', () => {
  it('wires the installed channel listeners on registration', () => {
    const channel = createMockChannel();
    installChannel(channel);

    registerService(mutableRecordLookupServiceDef);

    expect(channel.on).toHaveBeenCalledWith(SERVICE_SYNC_START, expect.any(Function));
    expect(channel.on).toHaveBeenCalledWith(SERVICE_SYNC_START_REPLY, expect.any(Function));
    expect(channel.on).toHaveBeenCalledWith(SERVICE_PATCHES, expect.any(Function));
  });

  it('throws when the addons channel is not installed', () => {
    installChannel(null);

    expect(() => registerService(mutableRecordLookupServiceDef)).toThrow(
      OpenServiceMissingChannelError
    );
  });
});

describe('server: command push', () => {
  it('broadcasts the post-mutation snapshot after a local command', async () => {
    const channel = createMockChannel();
    installChannel(channel);

    const service = registerService(mutableRecordLookupServiceDef);

    await service.commands.assignRecordField({ entryId: 'a', fieldKey: 'k', fieldValue: 'v' });

    const patches = channel.emit.mock.calls.filter(([event]) => event === SERVICE_PATCHES);
    // Exactly one: the broadcast echoes back on the shared bus, but its equal stamp fails `isNewer`
    // so it is dropped instead of re-broadcast.
    expect(patches).toHaveLength(1);
    expect(patches[0][1]).toEqual(
      expect.objectContaining({
        serviceId: recordServiceId,
        state: expect.objectContaining({ a: { k: 'v' } }),
        version: 1,
        clientId: expect.any(String),
      })
    );
    expect(service.queries.recordFields.get({ entryId: 'a' })).toEqual({ k: 'v' });
  });

  it('advances the version on each subsequent command, keeping a stable clientId', async () => {
    const channel = createMockChannel();
    installChannel(channel);

    const service = registerService(mutableRecordLookupServiceDef);

    await service.commands.assignRecordField({ entryId: 'a', fieldKey: 'k', fieldValue: '1' });
    await service.commands.assignRecordField({ entryId: 'a', fieldKey: 'k', fieldValue: '2' });

    const patches = channel.emit.mock.calls.filter(([event]) => event === SERVICE_PATCHES);
    expect(patches.map(([, p]) => (p as { version: number }).version)).toEqual([1, 2]);
    expect((patches[1][1] as { clientId: string }).clientId).toBe(
      (patches[0][1] as { clientId: string }).clientId
    );
    expect(service.queries.recordFields.get({ entryId: 'a' })).toEqual({ k: '2' });
  });
});

describe('server: sync-start initialization', () => {
  it('replies to a sync-start with its current snapshot and stamp', () => {
    const channel = createMockChannel();
    installChannel(channel);

    const service = registerService(mutableRecordLookupServiceDef);

    // Server adopts a peer patch: this both populates state and advances the server's stamp to the
    // peer's (version, clientId).
    channel.emitExternal(SERVICE_PATCHES, {
      serviceId: recordServiceId,
      state: { a: { k: 'v' } },
      version: 1,
      clientId: 'peer-1',
    });
    expect(service.queries.recordFields.get({ entryId: 'a' })).toEqual({ k: 'v' });

    // A different peer comes online and asks for current state; the server answers with the snapshot
    // it now holds, stamped with the version/clientId it adopted (not its own initial clientId).
    channel.emitExternal(SERVICE_SYNC_START, {
      serviceId: recordServiceId,
      clientId: 'peer-2',
    });

    expect(channel.emit).toHaveBeenCalledWith(
      SERVICE_SYNC_START_REPLY,
      expect.objectContaining({
        serviceId: recordServiceId,
        state: expect.objectContaining({ a: { k: 'v' } }),
        version: 1,
        clientId: 'peer-1',
      })
    );
  });

  it('does not reply to a sync-start for a different service id', () => {
    const channel = createMockChannel();
    installChannel(channel);

    registerService(mutableRecordLookupServiceDef);

    channel.emitExternal(SERVICE_SYNC_START, {
      serviceId: 'some-other-service',
      clientId: 'peer-2',
    });

    const replyCalls = channel.emit.mock.calls.filter(
      ([event]) => event === SERVICE_SYNC_START_REPLY
    );
    expect(replyCalls).toHaveLength(0);
  });
});

describe('server: patch application', () => {
  it('applies a version-gated patch from a peer', () => {
    const channel = createMockChannel();
    installChannel(channel);

    const service = registerService(mutableRecordLookupServiceDef);

    channel.emitExternal(SERVICE_PATCHES, {
      serviceId: recordServiceId,
      state: { entry: { marker: 'set' } },
      version: 1,
      clientId: 'peer',
    });

    expect(service.queries.recordFields.get({ entryId: 'entry' })).toEqual({ marker: 'set' });
  });

  it('drops a stale (lower-version) patch arriving after a newer one', () => {
    const channel = createMockChannel();
    installChannel(channel);

    const service = registerService(mutableRecordLookupServiceDef);

    channel.emitExternal(SERVICE_PATCHES, {
      serviceId: recordServiceId,
      state: { entry: { marker: 'new' } },
      version: 2,
      clientId: 'peer',
    });
    channel.emitExternal(SERVICE_PATCHES, {
      serviceId: recordServiceId,
      state: { entry: { marker: 'stale' } },
      version: 1,
      clientId: 'peer',
    });

    expect(service.queries.recordFields.get({ entryId: 'entry' })).toEqual({ marker: 'new' });
  });

  it('ignores patches for a different service id', () => {
    const channel = createMockChannel();
    installChannel(channel);

    const service = registerService(mutableRecordLookupServiceDef);

    channel.emitExternal(SERVICE_PATCHES, {
      serviceId: 'some-other-service',
      state: { entry: { x: '1' } },
      version: 1,
      clientId: 'peer',
    });

    expect(service.queries.recordFields.get({ entryId: 'entry' })).toBeNull();
  });

  it('drops malformed patches without throwing or mutating state', () => {
    const channel = createMockChannel();
    installChannel(channel);

    const service = registerService(mutableRecordLookupServiceDef);

    const malformed: unknown[] = [
      null,
      {},
      { serviceId: recordServiceId, state: { a: { k: 'v' } }, clientId: 'p' },
      { serviceId: recordServiceId, state: 'nope', version: 1, clientId: 'p' },
    ];

    for (const payload of malformed) {
      expect(() => channel.emitExternal(SERVICE_PATCHES, payload)).not.toThrow();
    }

    expect(service.queries.recordFields.get({ entryId: 'a' })).toBeNull();
  });
});

describe('server: teardown via clearRegistry', () => {
  it('detaches channel listeners so later patches are ignored', () => {
    const channel = createMockChannel();
    installChannel(channel);

    const service = registerService(mutableRecordLookupServiceDef);

    channel.emitExternal(SERVICE_PATCHES, {
      serviceId: recordServiceId,
      state: { entry: { marker: 'set' } },
      version: 1,
      clientId: 'peer',
    });
    expect(service.queries.recordFields.get({ entryId: 'entry' })).toEqual({ marker: 'set' });

    clearRegistry();

    expect(channel.off).toHaveBeenCalledWith(SERVICE_SYNC_START, expect.any(Function));
    expect(channel.off).toHaveBeenCalledWith(SERVICE_SYNC_START_REPLY, expect.any(Function));
    expect(channel.off).toHaveBeenCalledWith(SERVICE_PATCHES, expect.any(Function));

    // A strictly-newer patch after teardown must not reach the now-detached runtime.
    channel.emitExternal(SERVICE_PATCHES, {
      serviceId: recordServiceId,
      state: { entry: { marker: 'after' } },
      version: 2,
      clientId: 'peer',
    });
    expect(service.queries.recordFields.get({ entryId: 'entry' })).toEqual({ marker: 'set' });
  });
});

describe('server: bootstrap on registration', () => {
  it('emits a sync-start so a freshly-registered server can catch up', () => {
