      expect(states).toHaveLength(1);
      expect(states[0]).toMatchObject({
        data: null,
        error: undefined,
        status: 'success',
        loadStatus: 'idle',
        isSuccess: true,
        isPending: false,
        isError: false,
        isLoading: false,
        isInitialLoading: false,
        isRefreshing: false,
