import { Tag } from '../../../../shared/constants/tags.ts';
import type { DocsIndexEntry, IndexEntry, StoryIndex } from '../../../../types/modules/indexer.ts';
import { buildStaticFiles, clearRegistry, getService } from '../../server.ts';
import { registerTestModuleGraphService } from '../module-graph/module-graph.test-helpers.ts';
import { registerDocgenService } from './server.ts';
import type { DocgenPayload, DocgenProvider } from './types.ts';

beforeEach(() => {
  // registerDocgenService subscribes to `core/module-graph` and fails hard when it is missing, so
  // the dependency must be registered first (mirroring the dev-server, where it always is).
  registerTestModuleGraphService();
});

afterEach(() => {
  clearRegistry();
});

function makeStoryEntry(id: string, title = 'Comp'): IndexEntry {
  return {
    id,
    name: id.split('--').slice(1).join('--') || 'Default',
    title,
    type: 'story',
    subtype: 'story',
    importPath: `./${title.toLowerCase()}.stories.tsx`,
  };
}

function makeDocgenPayload(overrides: Partial<DocgenPayload> = {}): DocgenPayload {
  return {
    id: 'button',
    name: 'Button',
    path: './button.stories.tsx',
    jsDocTags: {},
    ...overrides,
  };
}

function makeGetIndex(entries: IndexEntry[]) {
  const index: StoryIndex = {
    v: 5,
    entries: Object.fromEntries(entries.map((entry) => [entry.id, entry])),
  };
  return () => Promise.resolve(index);
}

describe('docgen open service', () => {
  describe('extractDocgen command', () => {
    it('hands the resolved index entry to the provider, stores its payload, and returns it', async () => {
      const entry = makeStoryEntry('button--secondary', 'Button');
      const payload = makeDocgenPayload({ description: 'A button' });
      const provider = vi.fn<DocgenProvider>(async () => payload);

      const service = registerDocgenService({
        getIndex: makeGetIndex([entry]),
        docgenProvider: provider,
      });

      const returned = await service.commands.extractDocgen({ id: 'button' });

      expect(returned).toEqual(payload);
      expect(service.queries.docgen.get({ id: 'button' })).toEqual(payload);

      expect(provider).toHaveBeenCalledTimes(1);
      expect(provider.mock.calls[0][0]).toEqual({ entry });
    });

    it('prefers a story index entry over attached docs for the same component id', async () => {
      const storyEntry = makeStoryEntry('comp--default', 'Comp');
      const docsEntry = {
        id: 'comp--docs',
        name: 'Docs',
        title: 'Comp/Docs',
        type: 'docs',
        importPath: './comp.mdx',
        storiesImports: ['./wrong.stories.tsx'],
        tags: [Tag.ATTACHED_MDX, 'docs'],
      } satisfies DocsIndexEntry;

      const provider = vi.fn<DocgenProvider>(async () => makeDocgenPayload({ id: 'comp' }));

      const service = registerDocgenService({
        getIndex: makeGetIndex([docsEntry, storyEntry]),
        docgenProvider: provider,
      });

      await service.commands.extractDocgen({ id: 'comp' });

      expect(provider.mock.calls[0][0]).toEqual({ entry: storyEntry });
    });

    it('returns undefined and leaves state untouched when the provider returns undefined', async () => {
      const service = registerDocgenService({
        getIndex: makeGetIndex([makeStoryEntry('button--primary', 'Button')]),
        docgenProvider: async () => undefined,
      });

      const returned = await service.commands.extractDocgen({ id: 'button' });

      expect(returned).toBeUndefined();
      expect(service.queries.docgen.get({ id: 'button' })).toBeUndefined();
    });

    it('throws when no entry exists for the component id', async () => {
      const service = registerDocgenService({
        getIndex: makeGetIndex([makeStoryEntry('button--primary', 'Button')]),
        docgenProvider: async () => undefined,
      });

      await expect(service.commands.extractDocgen({ id: 'unknown' })).rejects.toThrow(
        /No story or attached docs entry was found for component id "unknown"/
      );
    });

    it('propagates provider errors out of the command', async () => {
      const service = registerDocgenService({
        getIndex: makeGetIndex([makeStoryEntry('button--primary', 'Button')]),
        docgenProvider: async () => {
          throw new Error('provider blew up');
        },
      });

      await expect(service.commands.extractDocgen({ id: 'button' })).rejects.toThrow(
        'provider blew up'
      );
    });
  });

  describe('docgenForAllComponents query', () => {
    it('returns every extracted component without filtering', async () => {
      const manifestStory = {
        ...makeStoryEntry('button--primary', 'Button'),
        tags: [Tag.MANIFEST],
      };
      const otherStory = makeStoryEntry('card--default', 'Card');

      const service = registerDocgenService({
        getIndex: makeGetIndex([manifestStory, otherStory]),
        docgenProvider: async ({ entry }) =>
          makeDocgenPayload({
            id: entry.importPath.includes('button') ? 'button' : 'card',
            name: entry.importPath.includes('button') ? 'Button' : 'Card',
            path: entry.importPath,
          }),
      });

      await expect(service.queries.docgenForAllComponents.loaded()).resolves.toEqual({
        button: makeDocgenPayload({
          id: 'button',
          name: 'Button',
          path: './button.stories.tsx',
        }),
        card: makeDocgenPayload({
          id: 'card',
          name: 'Card',
          path: './card.stories.tsx',
        }),
      });
    });
  });

  describe('extractAllDocgen command', () => {
    it('records one component`s failure without dropping every other component`s payload', async () => {
      const service = registerDocgenService({
        getIndex: makeGetIndex([
          makeStoryEntry('button--primary', 'Button'),
          makeStoryEntry('card--default', 'Card'),
        ]),
        docgenProvider: async ({ entry }) => {
          if (entry.importPath.includes('button')) {
            throw new TypeError('provider blew up');
          }
          return makeDocgenPayload({ id: 'card', name: 'Card', path: entry.importPath });
        },
      });

      await service.commands.extractAllDocgen(undefined);

      expect(service.queries.docgen.get({ id: 'card' })).toEqual(
        makeDocgenPayload({ id: 'card', name: 'Card', path: './card.stories.tsx' })
      );
      expect(service.queries.docgen.get({ id: 'button' })).toEqual({
        id: 'button',
        name: 'Button',
        path: './button.stories.tsx',
        jsDocTags: {},
        error: { name: 'TypeError', message: 'provider blew up' },
      });
    });
  });

  describe('docgen query', () => {
    it('returns undefined synchronously when nothing has been extracted yet', async () => {
      const service = registerDocgenService({
        getIndex: makeGetIndex([makeStoryEntry('button--primary', 'Button')]),
        docgenProvider: async () => makeDocgenPayload(),
      });

      expect(service.queries.docgen.get({ id: 'button' })).toBeUndefined();
    });

    it('.loaded() drives the load body which calls extractDocgen', async () => {
      const service = registerDocgenService({
        getIndex: makeGetIndex([makeStoryEntry('button--primary', 'Button')]),
        docgenProvider: async () => makeDocgenPayload({ description: 'from-loaded' }),
      });

      await expect(service.queries.docgen.loaded({ id: 'button' })).resolves.toEqual(
        makeDocgenPayload({ description: 'from-loaded' })
      );
    });

    it('.loaded() surfaces missing-component errors from the command', async () => {
      const service = registerDocgenService({
        getIndex: makeGetIndex([makeStoryEntry('button--primary', 'Button')]),
        docgenProvider: async () => undefined,
      });

      await expect(service.queries.docgen.loaded({ id: 'unknown' })).rejects.toThrow(
        /No story or attached docs entry was found for component id "unknown"/
      );
    });
  });

  describe('module graph hot refresh', () => {
    it('refreshes already-extracted components without loading every bumped component', async () => {
      const buttonEntry = makeStoryEntry('button--primary', 'Button');
      const cardEntry = makeStoryEntry('card--primary', 'Card');
      const provider = vi.fn<DocgenProvider>(async ({ entry }) =>
        makeDocgenPayload({
          id: entry.id.split('--')[0],
          name: entry.title,
          path: entry.importPath,
        })
      );
      const service = registerDocgenService({
        getIndex: makeGetIndex([buttonEntry, cardEntry]),
        docgenProvider: provider,
      });

      await service.queries.docgen.loaded({ id: 'button' });

      const moduleGraph = getService('core/module-graph', { internal: true });
      await moduleGraph.commands._applyGraphUpdate({
        storiesByFile: {},
        bumpedStoryFiles: ['./button.stories.tsx', './card.stories.tsx'],
      });

      await vi.waitFor(() =>
        expect(provider.mock.calls.map(([input]) => input.entry.importPath)).toEqual([
          './button.stories.tsx',
          './button.stories.tsx',
        ])
      );
    });

    it('refreshes already-extracted components when their story file changes', async () => {
      const buttonEntry = makeStoryEntry('button--primary', 'Button');
      const cardEntry = makeStoryEntry('card--primary', 'Card');
      const provider = vi.fn<DocgenProvider>(async ({ entry }) =>
        makeDocgenPayload({
          id: entry.id.split('--')[0],
          name: entry.title,
          path: entry.importPath,
        })
      );
      const service = registerDocgenService({
        getIndex: makeGetIndex([buttonEntry, cardEntry]),
        docgenProvider: provider,
      });

      await service.queries.docgen.loaded({ id: 'button' });

      const moduleGraph = getService('core/module-graph', { internal: true });
      await moduleGraph.commands._applyGraphUpdate({
        storiesByFile: {},
        bumpedStoryFiles: ['./button.stories.tsx'],
      });

      await vi.waitFor(() =>
        expect(provider.mock.calls.map(([input]) => input.entry.importPath)).toEqual([
          './button.stories.tsx',
          './button.stories.tsx',
        ])
      );
    });
  });

  describe('static build', () => {
    it('does not request docgen for component ids that only exist on unattached docs entries', async () => {
      const storyEntry = makeStoryEntry('button--primary', 'Button');
      const unattachedDocs = {
        id: 'orphan--docs',
        name: 'Docs',
        title: 'Orphan/Docs',
        type: 'docs',
        importPath: './orphan.mdx',
        storiesImports: [],
        tags: [Tag.UNATTACHED_MDX, 'docs'],
      } satisfies DocsIndexEntry;

      const provider = vi.fn<DocgenProvider>(async () => makeDocgenPayload());

      registerDocgenService({
        getIndex: makeGetIndex([storyEntry, unattachedDocs]),
        docgenProvider: provider,
      });

      const store = await buildStaticFiles();

      expect(provider).toHaveBeenCalledTimes(1);
      expect(provider.mock.calls[0][0].entry).toEqual(storyEntry);
      expect(Object.keys(store)).toEqual(['core/docgen/button.json']);
    });

    it('writes one docgen JSON per component id whose provider produced a payload', async () => {
      registerDocgenService({
        getIndex: makeGetIndex([
          makeStoryEntry('button--primary', 'Button'),
          makeStoryEntry('button--secondary', 'Button'),
          makeStoryEntry('card--default', 'Card'),
        ]),
        docgenProvider: async ({ entry }) => {
          const isButton = entry.importPath.includes('button');
          return makeDocgenPayload({
            id: isButton ? 'button' : 'card',
            name: isButton ? 'Button' : 'Card',
            path: entry.importPath,
            description: `from ${entry.importPath}`,
          });
        },
      });

      const store = await buildStaticFiles();

      expect(Object.keys(store).sort()).toEqual([
        'core/docgen/button.json',
        'core/docgen/card.json',
      ]);
      expect(store['core/docgen/button.json']).toMatchObject({
        components: {
          button: {
            id: 'button',
            name: 'Button',
            path: './button.stories.tsx',
            description: 'from ./button.stories.tsx',
            jsDocTags: {},
          },
        },
      });
    });
  });

  describe('provider middleware composition', () => {
    it('lets a wrapping provider delegate to nextDocgen and merge its output', async () => {
      const inner: DocgenProvider = async () => makeDocgenPayload({ name: 'inner-name' });

      const outer: DocgenProvider = async (input) => {
        const downstream = await inner(input);
        if (!downstream) {
          return undefined;
        }
        return { ...downstream, description: 'outer-description' };
      };

      const service = registerDocgenService({
        getIndex: makeGetIndex([makeStoryEntry('button--primary', 'Button')]),
        docgenProvider: outer,
      });

      await expect(service.queries.docgen.loaded({ id: 'button' })).resolves.toEqual(
        makeDocgenPayload({ name: 'inner-name', description: 'outer-description' })
      );
    });

    it('merges output from three stacked providers (identity → A → B)', async () => {
      const identity: DocgenProvider = async () => undefined;

      const providerA: DocgenProvider = async (input) => {
        await identity(input);
        return makeDocgenPayload({ name: 'A-name' });
      };

      const providerB: DocgenProvider = async (input) => {
        const downstream = await providerA(input);
        if (!downstream) {
          return undefined;
        }
        return {
          ...downstream,
          description: `${downstream.description ?? ''}B-description`,
        };
      };

      const service = registerDocgenService({
        getIndex: makeGetIndex([makeStoryEntry('button--primary', 'Button')]),
        docgenProvider: providerB,
      });

      await expect(service.queries.docgen.loaded({ id: 'button' })).resolves.toEqual(
        makeDocgenPayload({
          name: 'A-name',
          description: 'B-description',
        })
      );
    });

    it('propagates undefined from the bottom of the chain when no provider has docgen', async () => {
      const identity: DocgenProvider = async () => undefined;
      const passthrough: DocgenProvider = async (input) => identity(input);

      const service = registerDocgenService({
        getIndex: makeGetIndex([makeStoryEntry('button--primary', 'Button')]),
        docgenProvider: passthrough,
      });

      await service.commands.extractDocgen({ id: 'button' });
      expect(service.queries.docgen.get({ id: 'button' })).toBeUndefined();
    });
  });
});

import { getStoryImportPathFromEntry } from '../../../../common/utils/select-component-entry.ts';
import type { StoryIndex } from '../../../../types/modules/indexer.ts';
import { registerExtractionService } from '../extraction-service.server.ts';
import { docgenServiceDef } from './definition.ts';
import type { DocgenProvider } from './types.ts';

export type RegisterDocgenServiceOptions = {
  workingDir?: string;
  /**
   * Returns the current story index when a service needs it. Callers should bind this to a
   * pre-resolved generator so each call does not re-await generator initialization.
   */
  getIndex: () => Promise<StoryIndex>;
  /** Fully composed docgen provider chain from `presets.apply('experimental_docgenProvider', ...)`. */
  docgenProvider: DocgenProvider;
};

/** Registers the `core/docgen` open service against the process-global registry. */
export function registerDocgenService(options: RegisterDocgenServiceOptions) {
  return registerExtractionService(docgenServiceDef, {
    workingDir: options.workingDir ?? process.cwd(),
    getIndex: options.getIndex,
    provider: options.docgenProvider,
    buildErrorPayload: ({ id, entry, error }) => ({
      id,
      name: entry.title,
      path: getStoryImportPathFromEntry(entry) ?? entry.importPath,
      jsDocTags: {},
      error,
    }),
    queryName: 'docgen',
    extractCommand: 'extractDocgen',
    extractAllCommand: 'extractAllDocgen',
  });
}

// From the defining module, not the `types/modules/csf.ts` barrel: that barrel re-exports through
// the bare `storybook/internal/csf` specifier, which the portable `toolsets-docs` d.ts (this file
// is in its closure) must not reference — its guard allows no `storybook/*` imports.
import type { StrictArgTypes } from '../../../../csf/story.ts';
import type { IndexEntry } from '../../../../types/modules/indexer.ts';

/**
 * Caller-facing input to a docgen provider middleware.
 *
 * `entry` is the authoritative story-index entry for the requested component, selected with the
 * same rules as the React component manifest generator (`selectComponentEntriesByComponentId` in
 * `storybook/internal/common`): eligible story entries and attached docs, with story entries
 * preferred over attached docs for the same component id.
 */
export interface DocgenProviderInput {
  entry: IndexEntry;
}

/** Free-form error attached to a payload or subcomponent. */
export interface DocgenError {
  name: string;
  message: string;
}

/** Compact JSDoc tag map: tag name → list of tag values (e.g. `@example a` → `{ example: ['a'] }`). */
export type DocgenJsDocTags = Record<string, string[]>;

/**
 * Docgen payload returned by `core/docgen`'s `docgen` query.
 *
 * Component-only fields (props, descriptions, subcomponents). Story snippets and file-level
 * imports live in `core/story-docs` when `experimentalDocgenServer` is enabled.
 */
export interface DocgenPayload {
  id: string;
  name: string;
  /** CSF story file import path from the index entry (same as component manifest `path`). */
  path: string;
  description?: string;
  summary?: string;
  jsDocTags: DocgenJsDocTags;
  /** Renderer-converted argTypes derived from integration-specific docgen data at write time. */
  argTypes?: StrictArgTypes;
  subcomponents?: Record<string, DocgenSubcomponent>;
  error?: DocgenError;
  [key: string]: unknown;
}

/** Component-level summary + docgen for one subcomponent. */
export interface DocgenSubcomponent {
  name: string;
  path: string;
  description?: string;
  summary?: string;
  import?: string;
  jsDocTags: DocgenJsDocTags;
  /** Renderer-converted argTypes derived from integration-specific docgen data at write time. */
  argTypes?: StrictArgTypes;
  error?: DocgenError;
  [key: string]: unknown;
}

/**
 * A docgen provider: given a component's index entry, returns a complete {@link DocgenPayload} or
 * `undefined` when no docgen is available for the file.
 *
 * Providers are composed middleware-style inside the docgen worker — each wraps the previous one in
 * the chain and may delegate to it to merge with downstream output.
 *
 * **Merge convention.** When combining your output with downstream's, use spread
 * (`{ ...downstream, ...yourOverrides }`) and `downstream?.field ?? yours` rather than rebuilding
 * the payload field-by-field. Manual reconstruction silently drops any fields a future provider
 * (or future schema change) adds and your provider doesn't know about. `??` preserves explicit
 * values from downstream — including empty strings — so providers that intentionally set a field
 * are not overridden by a later provider's defaults.
 */
export type DocgenProvider = (input: DocgenProviderInput) => Promise<DocgenPayload | undefined>;

/**
 * Middleware that wraps the next provider in the docgen chain.
 *
 * The worker seeds the chain with an identity provider (returns `undefined`) and folds each
 * descriptor's middleware over it in registration order, so a later registrant wraps (and can
 * delegate to) the earlier ones.
 */
export type DocgenMiddleware = (nextDocgen: DocgenProvider) => DocgenProvider;

/**
 * Serializable descriptor a renderer or addon contributes via the `experimental_docgenProvider`
 * preset.
 *
 * Docgen extraction runs off the main thread in a long-lived worker owned by core. Because a
 * closure cannot cross a worker boundary, integrations describe their provider as data: a
 * `moduleSpecifier` pointing at a module that satisfies {@link DocgenWorkerModule}. Core collects
 * these descriptors (preserving preset order) and the worker imports and composes them.
 */
export interface DocgenProviderDescriptor<TOptions = unknown> {
  /** Absolute path to a module that exports {@link DocgenWorkerModule.createDocgenProvider}. */
  moduleSpecifier: string;
  /**
   * Configuration handed to the module's `createDocgenProvider`, for values the worker cannot
   * derive on its own (a workspace root, a tsconfig path, a framework option).
   *
   * The value is structured-cloned onto the worker thread, so it must be plain JSON-ish data.
   * Functions, closures and class instances are not permitted: they throw at `postMessage` time.
   */
  options?: TOptions;
}

/**
 * Contract a worker-target docgen module must satisfy. The worker imports the descriptor's
 * `moduleSpecifier` and calls `createDocgenProvider()` once to build the middleware it folds into
 * the provider chain. Integrations implement only this factory — they never touch threading.
 */
export interface DocgenWorkerModule<TOptions = unknown> {
  createDocgenProvider: (options?: TOptions) => DocgenMiddleware | Promise<DocgenMiddleware>;
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import type { DocgenProviderDescriptor } from '../types.ts';
import type { DocgenWorkerRequest, DocgenWorkerResponse } from './protocol.ts';

interface FakeWorker {
  posted: DocgenWorkerRequest[];
  postMessage: ReturnType<typeof vi.fn>;
  terminate: ReturnType<typeof vi.fn>;
  unref: ReturnType<typeof vi.fn>;
  ref: ReturnType<typeof vi.fn>;
  /** `message` listeners registered at the moment `unref()` ran; see the ordering test below. */
  messageListenersAtUnref: number;
  emit: (event: string, ...args: unknown[]) => boolean;
}

const fakeWorkers: FakeWorker[] = [];

vi.mock('node:worker_threads', async () => {
  const { EventEmitter: NodeEventEmitter } = await import('node:events');

  class FakeWorkerImpl extends NodeEventEmitter {
    posted: DocgenWorkerRequest[] = [];
    constructor() {
      super();
      fakeWorkers.push(this as unknown as FakeWorker);
    }
    postMessage = vi.fn((msg: DocgenWorkerRequest) => {
      this.posted.push(msg);
    });
    terminate = vi.fn(async () => 0);
    messageListenersAtUnref = -1;
    unref = vi.fn(() => {
      this.messageListenersAtUnref = this.listenerCount('message');
    });
    ref = vi.fn();
  }

  return { Worker: FakeWorkerImpl };
});

vi.mock('node:fs', () => ({ existsSync: vi.fn(() => true) }));

vi.mock('../../../../utils/module.ts', () => ({
  // Drive letter included so `fileURLToPath()` accepts this URL on Windows too.
  importMetaResolve: vi.fn(() => 'file:///C:/fake/storybook/docgen-worker.js'),
}));

vi.mock('storybook/internal/node-logger', { spy: true });

const loadModule = async () => import('./docgen-worker-client.ts');

const DESCRIPTORS: DocgenProviderDescriptor[] = [
  { moduleSpecifier: '/fake/react/docgen-worker.js' },
];

function ackInit(worker: FakeWorker, error?: { name: string; message: string }) {
  worker.emit(
    'message',
    (error ? { type: 'init', error } : { type: 'init' }) satisfies DocgenWorkerResponse
  );
}

beforeEach(() => {
  fakeWorkers.length = 0;
});

afterEach(() => {
  vi.clearAllMocks();
  fakeWorkers.length = 0;
});

describe('createDocgenWorkerClient', () => {
  it('returns undefined when the compiled worker script is missing', async () => {
    const fs = await import('node:fs');
    vi.mocked(fs.existsSync).mockReturnValueOnce(false);

    const { createDocgenWorkerClient } = await loadModule();
    expect(createDocgenWorkerClient(DESCRIPTORS)).toBeUndefined();
    expect(fakeWorkers).toHaveLength(0);
  });

  it('does not spawn a worker until the first extract', async () => {
    const { createDocgenWorkerClient } = await loadModule();
    const client = createDocgenWorkerClient(DESCRIPTORS);

    expect(client).toBeDefined();
    expect(fakeWorkers).toHaveLength(0);
  });

  it('spawns the worker lazily on the first extract and posts init with descriptors', async () => {
    const { createDocgenWorkerClient } = await loadModule();
    const client = createDocgenWorkerClient(DESCRIPTORS)!;

    const promise = client.extract({ id: 'button--primary' } as any);
    const worker = fakeWorkers[0];

    expect(fakeWorkers).toHaveLength(1);
    expect(worker.posted[0]).toEqual({ type: 'init', descriptors: DESCRIPTORS });
    expect(worker.unref).not.toHaveBeenCalled();

    ackInit(worker);
    await Promise.resolve();
    const extractMsg = worker.posted.find((m) => m.type === 'extract') as { id: number };
    // Loose on purpose: a transient unref can land before the extract continuation runs.
    expect(worker.ref).toHaveBeenCalled();
    worker.emit('message', {
      type: 'extract',
      id: extractMsg.id,
      payload: { id: 'button', name: 'Button', path: './button.stories.tsx', jsDocTags: {} },
    } satisfies DocgenWorkerResponse);
    await expect(promise).resolves.toMatchObject({ id: 'button' });
    const lastRef = Math.max(...worker.ref.mock.invocationCallOrder);
    const lastUnref = Math.max(...worker.unref.mock.invocationCallOrder);
    expect(lastUnref).toBeGreaterThan(lastRef);

    // Attaching a `message` listener re-refs the port, so unref before that holds the loop open.
    expect(worker.messageListenersAtUnref).toBeGreaterThan(0);
  });
});

describe('DocgenWorkerClient.extract', () => {
  it('waits for init, dispatches the entry, and resolves the payload', async () => {
    const { createDocgenWorkerClient } = await loadModule();
    const client = createDocgenWorkerClient(DESCRIPTORS)!;

    const entry = { id: 'button--primary', importPath: './button.stories.tsx' } as any;
    const promise = client.extract(entry);
    const worker = fakeWorkers[0];

    expect(worker.posted.filter((m) => m.type === 'extract')).toHaveLength(0);
    ackInit(worker);
    await Promise.resolve();

    const extractMsg = worker.posted.find((m) => m.type === 'extract');
    expect(extractMsg).toMatchObject({ type: 'extract', entry });

    worker.emit('message', {
      type: 'extract',
      id: (extractMsg as { id: number }).id,
      payload: { id: 'button', name: 'Button', path: './button.stories.tsx', jsDocTags: {} },
    } satisfies DocgenWorkerResponse);

    await expect(promise).resolves.toMatchObject({ id: 'button', name: 'Button' });
  });

  it('rejects extract calls when init fails', async () => {
    const { createDocgenWorkerClient } = await loadModule();
    const client = createDocgenWorkerClient(DESCRIPTORS)!;

    const promise = client.extract({ id: 'x' } as any);
    const worker = fakeWorkers[0];
    ackInit(worker, { name: 'Error', message: 'boom' });

    await expect(promise).rejects.toThrow('boom');
  });

  it('rejects an extract awaiting init when the worker exits before init', async () => {
    const { createDocgenWorkerClient } = await loadModule();
    const client = createDocgenWorkerClient(DESCRIPTORS)!;

    const promise = client.extract({ id: 'x' } as any);
    const worker = fakeWorkers[0];
    worker.emit('exit', 1);

    await expect(promise).rejects.toThrow(/exited unexpectedly/);
  });

  it('rejects with the error name/message from a failed extraction', async () => {
    const { createDocgenWorkerClient } = await loadModule();
    const client = createDocgenWorkerClient(DESCRIPTORS)!;

    const promise = client.extract({ id: 'x' } as any);
    const worker = fakeWorkers[0];
    ackInit(worker);
    await Promise.resolve();

    const extractMsg = worker.posted.find((m) => m.type === 'extract') as { id: number };
    worker.emit('message', {
      type: 'extract',
      id: extractMsg.id,
      error: { name: 'DocgenError', message: 'extraction exploded' },
    } satisfies DocgenWorkerResponse);

    await expect(promise).rejects.toThrowError(
      expect.objectContaining({ name: 'DocgenError', message: 'extraction exploded' })
    );
  });

  it('rejects in-flight extractions when the worker exits unexpectedly', async () => {
    const { createDocgenWorkerClient } = await loadModule();
    const client = createDocgenWorkerClient(DESCRIPTORS)!;

    const promise = client.extract({ id: 'x' } as any);
    const worker = fakeWorkers[0];
    ackInit(worker);
    await Promise.resolve();

    worker.emit('exit', 1);

    await expect(promise).rejects.toThrow(/exited unexpectedly/);
  });
});

import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { Worker } from 'node:worker_threads';

import { logger } from 'storybook/internal/node-logger';

import type { IndexEntry } from '../../../../../types/modules/indexer.ts';
import { importMetaResolve } from '../../../../utils/module.ts';
import type { ErrorLike } from '../../module-graph/types.ts';
import type { DocgenPayload, DocgenProviderDescriptor } from '../types.ts';
import type { DocgenWorkerRequest, DocgenWorkerResponse } from './protocol.ts';

// Resolved via the export map, not a hard-coded dist path, so strict layouts like pnpm's work.
const WORKER_SPECIFIER = 'storybook/internal/docgen-worker';

const DEFAULT_TASK_TIMEOUT_MS = 120_000;

interface Pending {
  resolve: (payload: DocgenPayload | undefined) => void;
  reject: (error: unknown) => void;
  timer?: NodeJS.Timeout;
}

export interface DocgenWorkerClient {
  extract(entry: IndexEntry): Promise<DocgenPayload | undefined>;
}

function errorLikeToError(errorLike: ErrorLike): Error {
  const error = new Error(errorLike.message);
  if (errorLike.name) {
    error.name = errorLike.name;
  }
  if (errorLike.stack) {
    error.stack = errorLike.stack;
  }
  return error;
}

// One worker, never a pool: extraction serializes on a single warm TypeScript program, so extra
// threads would only duplicate multi-second program builds and their memory.
class DocgenWorker implements DocgenWorkerClient {
  private readonly worker: Worker;
  private readonly pending = new Map<number, Pending>();
  private readonly ready: Promise<void>;
  private rejectReady: (error: unknown) => void = () => undefined;
  private nextId = 0;
  private dead = false;

  constructor(
    scriptPath: string,
    descriptors: DocgenProviderDescriptor[],
    private readonly taskTimeoutMs = DEFAULT_TASK_TIMEOUT_MS
  ) {
    this.worker = new Worker(scriptPath);
    this.worker.on('message', (msg: DocgenWorkerResponse) => this.handleMessage(msg));
    this.worker.on('error', (error) => this.fail(error));
    this.worker.on('exit', (code) => {
      if (!this.dead) {
        this.fail(new Error(`docgen worker exited unexpectedly with code ${code}`));
      }
    });

    this.ready = new Promise<void>((resolve, reject) => {
      this.rejectReady = reject;
      const onMessage = (msg: DocgenWorkerResponse) => {
        if (msg.type !== 'init') {
          return;
        }
        this.worker.off('message', onMessage);
        if (msg.error) {
          reject(errorLikeToError(msg.error));
        } else {
          resolve();
        }
      };
      this.worker.on('message', onMessage);
    });
    // Prevents an unhandled rejection; `extract` still awaits `ready` and surfaces the error.
    this.ready.catch(() => undefined);

    // Spawn is lazy, so an extract is always imminent: stay referenced until `ready` settles.
    this.ready.finally(() => this.keepProcessAliveWhileBusy()).catch(() => undefined);

    this.post({ type: 'init', descriptors });
  }

  async extract(entry: IndexEntry): Promise<DocgenPayload | undefined> {
    if (this.dead) {
      throw new Error('docgen worker is no longer running');
    }
    await this.ready;
    return new Promise<DocgenPayload | undefined>((resolve, reject) => {
      const id = this.nextId++;
      const pending: Pending = { resolve, reject };
      if (this.taskTimeoutMs > 0) {
        pending.timer = setTimeout(() => {
          this.pending.delete(id);
          this.keepProcessAliveWhileBusy();
          reject(new Error(`docgen worker extract ${id} timed out after ${this.taskTimeoutMs}ms`));
        }, this.taskTimeoutMs);
        pending.timer.unref?.();
      }
      this.pending.set(id, pending);
      this.keepProcessAliveWhileBusy();
      this.post({ type: 'extract', id, entry });
    });
  }

  private keepProcessAliveWhileBusy(): void {
    if (this.pending.size > 0) {
      this.worker.ref();
    } else {
      this.worker.unref();
    }
  }

  private post(msg: DocgenWorkerRequest): void {
    this.worker.postMessage(msg);
  }

  private handleMessage(msg: DocgenWorkerResponse): void {
    if (msg.type !== 'extract') {
      return;
    }
    const pending = this.pending.get(msg.id);
    if (!pending) {
      return;
    }
    if (pending.timer) {
      clearTimeout(pending.timer);
    }
    this.pending.delete(msg.id);
    this.keepProcessAliveWhileBusy();
    if (msg.error) {
      pending.reject(errorLikeToError(msg.error));
    } else {
      pending.resolve(msg.payload);
    }
  }

  private fail(error: Error): void {
    if (this.dead) {
      return;
    }
    logger.debug(`docgen worker failure: ${error.message}`);
    this.dead = true;
    // Without this, an `extract` awaiting `ready` hangs when the worker dies before `init`.
    this.rejectReady(error);
    this.rejectAllPending(error);
    this.worker.terminate().catch(() => 0);
  }

  private rejectAllPending(error: Error): void {
    for (const [, pending] of this.pending) {
      if (pending.timer) {
        clearTimeout(pending.timer);
      }
      pending.reject(error);
    }
    this.pending.clear();
    this.worker.unref();
  }
}

function resolveWorkerScriptPath(): string | undefined {
  try {
    const scriptPath = fileURLToPath(importMetaResolve(WORKER_SPECIFIER));
    return existsSync(scriptPath) ? scriptPath : undefined;
  } catch {
    return undefined;
  }
}

// The thread is spawned on the first extract, not here: nothing extracts until a story renders, so
// an eager spawn would only contend with the dev server's cold start.
export function createDocgenWorkerClient(
  descriptors: DocgenProviderDescriptor[]
): DocgenWorkerClient | undefined {
  const scriptPath = resolveWorkerScriptPath();
  if (!scriptPath) {
    logger.debug(
      'docgen worker disabled: compiled worker script not found (running from source without a build?)'
    );
    return undefined;
  }

  let worker: DocgenWorker | undefined;

  return {
    async extract(entry) {
      worker ??= new DocgenWorker(scriptPath, descriptors);
      return worker.extract(entry);
    },
  };
}

/**
 * Worker-thread entry point for docgen extraction.
 *
 * Spawned once by {@link ./docgen-worker-client.ts} and kept alive for the dev server's lifetime so
 * the TypeScript program(s) each provider builds stay warm across requests. On `init` it imports
 * every {@link DocgenProviderDescriptor}'s module and folds them into a single provider chain; on
 * `extract` it runs that chain for one component and posts the resulting payload back. Running here
 * keeps the synchronous, CPU-bound TypeScript work off the main event loop so it never starves the
 * Vite dev server during first render.
 */
import { parentPort } from 'node:worker_threads';
import { pathToFileURL } from 'node:url';

import type { IndexEntry } from '../../../../../types/modules/indexer.ts';
import { errorToErrorLike } from '../../module-graph/types.ts';
import type {
  DocgenMiddleware,
  DocgenProvider,
  DocgenProviderDescriptor,
  DocgenWorkerModule,
} from '../types.ts';
import type { DocgenWorkerRequest, DocgenWorkerResponse } from './protocol.ts';

if (!parentPort) {
  throw new Error('docgen worker must be run as a worker thread');
}

// Capture into a const so TypeScript keeps the non-null narrowing inside the async handlers and the
// message listener below (it won't narrow the mutable `parentPort` binding across those closures).
const port = parentPort;

/** Identity provider that seeds the chain; the bottom of the stack has no docgen to contribute. */
const seedProvider: DocgenProvider = async () => undefined;

/** Resolved once per worker on `init`; every `extract` awaits it. */
let providerPromise: Promise<DocgenProvider> | undefined;

async function composeProvider(descriptors: DocgenProviderDescriptor[]): Promise<DocgenProvider> {
  let provider = seedProvider;
  for (const descriptor of descriptors) {
    const moduleUrl = pathToFileURL(descriptor.moduleSpecifier).href;
    const mod = (await import(moduleUrl)) as Partial<DocgenWorkerModule>;
    if (typeof mod.createDocgenProvider !== 'function') {
      throw new Error(
        `docgen worker module "${descriptor.moduleSpecifier}" does not export createDocgenProvider`
      );
    }
    const middleware: DocgenMiddleware = await mod.createDocgenProvider(descriptor.options);
    provider = middleware(provider);
  }
  return provider;
}

async function handleInit(descriptors: DocgenProviderDescriptor[]): Promise<void> {
  try {
    providerPromise = composeProvider(descriptors);
    await providerPromise;
    port.postMessage({ type: 'init' } satisfies DocgenWorkerResponse);
  } catch (error) {
    providerPromise = undefined;
    port.postMessage({
      type: 'init',
      error: errorToErrorLike(error),
    } satisfies DocgenWorkerResponse);
  }
}

async function handleExtract(id: number, entry: IndexEntry): Promise<void> {
  try {
    if (!providerPromise) {
      throw new Error('docgen worker received an extract request before init');
    }
    const provider = await providerPromise;
    const payload = await provider({ entry });
    port.postMessage({ type: 'extract', id, payload } satisfies DocgenWorkerResponse);
  } catch (error) {
    port.postMessage({
      type: 'extract',
      id,
      error: errorToErrorLike(error),
    } satisfies DocgenWorkerResponse);
  }
}

port.on('message', (msg: DocgenWorkerRequest) => {
  switch (msg.type) {
    case 'init':
      void handleInit(msg.descriptors);
      return;
    case 'extract':
      void handleExtract(msg.id, msg.entry);
      return;
    default: {
      const _exhaustive: never = msg;
      throw new Error(`docgen worker received unknown message: ${JSON.stringify(_exhaustive)}`);
    }
  }
});

/**
 * Message protocol between the docgen worker client (main thread) and the worker
 * ({@link ./docgen-worker.ts}). All payloads are structured-clone-safe so they can cross the
 * `postMessage` boundary.
 *
 * Responses are success/failure unions discriminated by the presence of an {@link ErrorLike}
 * `error` (mirroring `ModuleGraphStatus`), rather than an `ok` flag with nullable fields — a
 * response either carries its result or an error, never an ambiguous mix.
 */
import type { IndexEntry } from '../../../../../types/modules/indexer.ts';
import type { ErrorLike } from '../../module-graph/types.ts';
import type { DocgenPayload, DocgenProviderDescriptor } from '../types.ts';

/** Sent once, right after spawn, to compose the provider chain inside the worker. */
export interface DocgenWorkerInitRequest {
  type: 'init';
  descriptors: DocgenProviderDescriptor[];
}

/** Sent per component to extract its docgen payload. `id` correlates the response. */
export interface DocgenWorkerExtractRequest {
  type: 'extract';
  id: number;
  entry: IndexEntry;
}

export type DocgenWorkerRequest = DocgenWorkerInitRequest | DocgenWorkerExtractRequest;

/** Chain composition succeeded; the worker is ready for extract requests. */
export interface DocgenWorkerInitSuccess {
  type: 'init';
  error?: undefined;
}

/** Chain composition failed; the worker is unusable. */
export interface DocgenWorkerInitFailure {
  type: 'init';
  error: ErrorLike;
}

export type DocgenWorkerInitResponse = DocgenWorkerInitSuccess | DocgenWorkerInitFailure;

/** Extraction succeeded; `payload` is the result (absent when no provider produced docgen). */
export interface DocgenWorkerExtractSuccess {
  type: 'extract';
  id: number;
  payload?: DocgenPayload;
  error?: undefined;
}

/** Extraction threw; `error` describes the failure. */
export interface DocgenWorkerExtractFailure {
  type: 'extract';
  id: number;
  error: ErrorLike;
}

export type DocgenWorkerExtractResponse = DocgenWorkerExtractSuccess | DocgenWorkerExtractFailure;

export type DocgenWorkerResponse = DocgenWorkerInitResponse | DocgenWorkerExtractResponse;

import invariant from 'tiny-invariant';

import {
  getStoryImportPathFromEntry,
  selectComponentEntriesByComponentId,
} from '../../../common/utils/select-component-entry.ts';
import { OpenServiceDocgenMissingComponentError } from '../../../server-errors.ts';
import type { IndexEntry, StoryIndex } from '../../../types/modules/indexer.ts';
import { getService, registerService } from '../server.ts';
import type {
  CommandCtx,
  Commands,
  Queries,
  ServiceDefinition,
  ServiceRegistrationOptions,
} from '../types.ts';
import type { ModuleGraphService } from './module-graph/definition.ts';
import { toStoryIndexPath } from './module-graph/types.ts';

/** Extraction services key provider-extracted payloads by component id under `components`. */
type ExtractionServiceState = { components: Record<string, unknown> };

/**
 * The component-keyed query whose synchronous `.get({ id })` reports whether a payload is currently
 * stored: it returns the payload, or `undefined` when nothing has been extracted for that id. `.get()`
 * never fires the query's `load`, so reading it cannot trigger a behind-the-scenes extraction.
 */
type ComponentPayloadQuery = { get(input: { id: string }): unknown };

type ExtractionProvider<TPayload> = (input: { entry: IndexEntry }) => Promise<TPayload | undefined>;

/** The `{ name, message }` shape both extraction payloads carry under `error`. */
export type ExtractionError = { name: string; message: string };

const toExtractionError = (error: unknown): ExtractionError =>
  error instanceof Error
    ? { name: error.name, message: error.message }
    : { name: 'Error', message: String(error) };

export type RegisterExtractionServiceOptions<TPayload, TQueries, TCommands> = {
  workingDir: string;
  getIndex: () => Promise<StoryIndex>;
  provider: ExtractionProvider<TPayload>;
  /**
   * Builds the payload stored for a component whose provider threw during the fan-out.
   *
   * Supplied per service because the payload shapes differ and both are validated against their
   * service's output schema.
   */
  buildErrorPayload: (input: { id: string; entry: IndexEntry; error: ExtractionError }) => TPayload;
  /**
   * Query whose `staticInputs` enumerate the eligible component ids, and whose `.get({ id })` the
   * hot-refresh subscription reads to decide which components are already extracted. Typed as a key
   * of the service's queries so the runtime query handle resolves without a cast.
   */
  queryName: keyof TQueries & string;
  /** Command that extracts and stores one component's payload. Keyed against the service's commands. */
  extractCommand: keyof TCommands & string;
  /** Command that extracts every component in the story index. Keyed against the service's commands. */
  extractAllCommand: keyof TCommands & string;
};

/**
 * Re-extracts already-cached components when the module graph reports story file changes.
 *
 * `latestStoryChanges` reports `{ revision, storyFiles }`. The revision is the authoritative
 * "something changed" trigger; `storyFiles` is an optimization hint that is sometimes legitimately
 * empty (e.g. after a story-index invalidation). When the hint is empty we refresh every
 * already-extracted component; when populated we refresh only those mapped from the bumped files.
 */
function subscribeExtractionServiceRefresh(
  moduleGraph: ModuleGraphService,
  options: {
    workingDir: string;
    getIndex: () => Promise<StoryIndex>;
    query: ComponentPayloadQuery;
    refreshComponent: (componentId: string) => Promise<unknown>;
  }
) {
  const refreshExtracted = async (componentIds: Iterable<string>) => {
    const idsToRefresh = Array.from(componentIds).filter(
      (id) => options.query.get({ id }) !== undefined
    );
    if (idsToRefresh.length === 0) {
      return;
    }
    await Promise.all(
      idsToRefresh.map((id) => options.refreshComponent(id).catch(() => undefined))
    );
  };

  moduleGraph.queries.latestStoryChanges.subscribe(undefined, async ({ data }) => {
    if (!data || data.revision === 0) {
      return;
    }

    const { storyFiles } = data;

    const componentEntries = selectComponentEntriesByComponentId(
      Object.values((await options.getIndex()).entries)
    );

    if (storyFiles.length === 0) {
      await refreshExtracted(componentEntries.keys());
      return;
    }

    const componentEntryCandidates = Array.from(componentEntries)
      .map(([id, entry]) => {
        const storyFilePath = getStoryImportPathFromEntry(entry);
        if (!storyFilePath) {
          return undefined;
        }
        return {
          id,
          storyIndexPath: toStoryIndexPath(storyFilePath, options.workingDir),
        };
      })
      .filter((candidate) => candidate !== undefined);

    const bumpedComponentIds = new Set<string>();
    for (const storyFile of storyFiles) {
      const componentEntry = componentEntryCandidates.find(
        (candidate) => candidate.storyIndexPath === storyFile
      );
      if (!componentEntry) {
        continue;
      }
      bumpedComponentIds.add(componentEntry.id);
    }

    await refreshExtracted(bumpedComponentIds);
  });
}

/**
 * Registers one component-id-keyed extraction service (`core/docgen` or `core/story-docs`).
 *
 * Both services share the same wiring: a `staticInputs` enumeration over the eligible component
 * entries, an `extract` command that runs the provider chain and stores the payload, an
 * `extractAll` command that fans out over the index, and a module-graph subscription that re-extracts
 * already-extracted components when their source files change. The per-component pick and the
 * `staticInputs` enumeration both use {@link selectComponentEntriesByComponentId} so a component id
 * always resolves to the same index entry.
 *
 * Requires the `core/module-graph` service to be registered (it always is in the dev server).
 */
export function registerExtractionService<
  TState extends ExtractionServiceState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
>(
  definition: ServiceDefinition<TState, TQueries, TCommands>,
  options: RegisterExtractionServiceOptions<TState['components'][string], TQueries, TCommands>
) {
  const {
    workingDir,
    getIndex,
    provider,
    buildErrorPayload,
    queryName,
    extractCommand,
    extractAllCommand,
  } = options;

  // The registration object below is built with computed keys and cast to `ServiceRegistrationOptions`,
  // which defeats TS's per-key checking. Assert the names exist on the definition so a typo fails here
  // instead of silently registering nothing (and later calling an `undefined` command in the refresh).
  invariant(
    queryName in definition.queries,
    `Extraction service "${definition.id}" has no query named "${queryName}".`
  );
  invariant(
    extractCommand in definition.commands && extractAllCommand in definition.commands,
    `Extraction service "${definition.id}" is missing command "${extractCommand}" or "${extractAllCommand}".`
  );

  const resolveComponentEntries = async () =>
    selectComponentEntriesByComponentId(Object.values((await getIndex()).entries));

  const extractComponent = async (
    ctx: CommandCtx<TState>,
    id: string
  ): Promise<TState['components'][string] | undefined> => {
    const entry = (await resolveComponentEntries()).get(id);

    if (!entry) {
      throw new OpenServiceDocgenMissingComponentError({ id });
    }

    const payload = await provider({ entry });

    if (!payload) {
      ctx.self.setState((state) => {
        delete state.components[id];
      });
      return undefined;
    }

    ctx.self.setState((state) => {
      state.components[id] = payload;
    });
    return payload;
  };

  const runtime = registerService(definition, {
    queries: {
      [queryName]: {
        staticInputs: async () => {
          const eligible = await resolveComponentEntries();
          return Array.from(eligible.keys(), (id) => ({ id }));
        },
      },
    },
    commands: {
      [extractCommand]: {
        handler: (input: { id: string }, ctx: CommandCtx<TState>) =>
          extractComponent(ctx, input.id),
      },
      [extractAllCommand]: {
        handler: async (_input: undefined, ctx: CommandCtx<TState>) => {
          const componentEntries = await resolveComponentEntries();
          await Promise.all(
            Array.from(componentEntries, ([id, entry]) =>
              // A provider is not required to be total: `Promise.all` rejects on the first
              // rejection, so an unguarded fan-out lets one component's failure discard every other
              // component's payload.
              extractComponent(ctx, id).catch((error: unknown) => {
                const payload = buildErrorPayload({ id, entry, error: toExtractionError(error) });
                ctx.self.setState((state) => {
                  state.components[id] = payload;
                });
              })
            )
          );
        },
      },
    },
  } as unknown as ServiceRegistrationOptions<TState, TQueries, TCommands>);

  const moduleGraph = getService('core/module-graph', { internal: true });
  subscribeExtractionServiceRefresh(moduleGraph, {
    workingDir,
    getIndex,
    query: runtime.queries[queryName],
    refreshComponent: (id) =>
      (runtime.commands as Record<string, (input: { id: string }) => Promise<unknown>>)[
        extractCommand
      ]({ id }),
  });

  return runtime;
}

import * as v from 'valibot';

import { defineService } from '../../service-definition.ts';
import type { ServiceInstanceOf } from '../../types.ts';
import type { ModuleGraphServiceState } from './types.ts';
import { toStoryIndexPath } from './types.ts';

const errorLikeSchema: v.GenericSchema = v.object({
  message: v.pipe(v.string(), v.description('Human-readable error message.')),
  name: v.optional(v.pipe(v.string(), v.description('Error class/name, when available.'))),
  stack: v.optional(v.pipe(v.string(), v.description('Stack trace, when available.'))),
  cause: v.optional(v.lazy(() => errorLikeSchema)),
});

const moduleGraphStatusSchema = v.variant('value', [
  v.object({
    value: v.literal('booting'),
  }),
  v.object({
    value: v.literal('ready'),
  }),
  v.object({
    value: v.literal('error'),
    error: v.pipe(
      errorLikeSchema,
      v.description('Serializable error describing why the module graph failed unexpectedly.')
    ),
  }),
  v.object({
    value: v.literal('unavailable'),
    reason: v.pipe(
      v.string(),
      v.description(
        'Human-readable reason why the current builder/runtime cannot provide module graph functionality.'
      )
    ),
    error: v.optional(
      v.pipe(
        errorLikeSchema,
        v.description('Optional serializable error reported by the builder adapter.')
      )
    ),
  }),
]);

/**
 * Reverse index shape `sourceFile -> storyFile -> breadth-first-search depth`. The depth is the
 * shortest number of import edges between the source file and the affected story file.
 */
const storyIndexPathSchema = v.pipe(
  v.string(),
  v.description('A story-index-style relative path such as `./src/Button.stories.tsx`.')
);
const storyDependencyDepthSchema = v.pipe(
  v.number(),
  v.description(
    'Breadth-first-search depth: the shortest number of import edges between the source file and this story file.'
  )
);
const storiesByFileSchema = v.record(
  storyIndexPathSchema,
  v.record(storyIndexPathSchema, storyDependencyDepthSchema)
);

/** Queries with no caller input — only `undefined` is accepted. Reused across several queries. */
const noInputSchema = v.undefined();

export type { ModuleGraphServiceState } from './types.ts';

export const moduleGraphServiceDef = defineService({
  id: 'core/module-graph',
  internal: true,
  description:
    'Story module dependency graph: reverse index from source files to story files, with reactive updates.',
  initialState: {
    workingDir: process.cwd(),
    status: { value: 'booting' },
    graphRevision: 0,
    storiesByFile: {},
    storyChangeRevisions: {},
    latestChangedStoryFiles: [],
  } as ModuleGraphServiceState,
  queries: {
    storiesForFiles: {
      description:
        'Returns, for each input file (same order), story-index-relative story files that depend on it and their breadth-first-search depth: the shortest number of import edges between the input file and the story file.',
      input: v.object({
        files: v.pipe(
          v.array(
            v.pipe(
              v.string(),
              v.description(
                'Input source file path. Accepts absolute paths, story-index-style relative paths with `./`, or relative paths without `./`.'
              )
            )
          ),
          v.description('Source files to look up. Output arrays match this input order.')
        ),
      }),
      output: v.array(
        v.array(
          v.object({
            storyFile: v.pipe(
              storyIndexPathSchema,
              v.description(
                'Affected story file, returned in the same `./`-prefixed relative import-path format used by the story index.'
              )
            ),
            depth: storyDependencyDepthSchema,
          })
        )
      ),
      handler: (input, ctx) => {
        const { workingDir } = ctx.self.state;
        return input.files.map((file) => {
          const entries = ctx.self.state.storiesByFile[toStoryIndexPath(file, workingDir)];
          if (!entries) {
            return [];
          }
          return Object.entries(entries).map(([storyFile, depth]) => ({
            storyFile,
            depth,
          }));
        });
      },
    },
    status: {
      description:
        'Current module graph lifecycle status. `booting` means the graph is still expected to become ready; `ready` means query state is populated; `error` means an unexpected graph failure; `unavailable` means the current builder/runtime cannot provide module graph functionality.',
      input: noInputSchema,
      output: moduleGraphStatusSchema,
      load: async (_input, ctx) => {
        await ctx.self.commands._waitForSettledEngine(undefined);
      },
      handler: (_input, ctx) => ctx.self.state.status,
    },
    graphRevision: {
      description:
        'Monotonic revision counter for module graph changes, advanced only by in-graph file changes and story-index reconciliation (out-of-graph file changes never advance it). Omit the input to watch the entire graph. Provide `storyFiles` to scope the watch to specific stories: returns the highest revision at which any of those story subgraphs last changed (0 if none have changed yet, or for unknown stories).',
      input: v.optional(
        v.object({
          storyFiles: v.array(
            v.pipe(
              v.string(),
              v.description(
                'Story file to scope the watch to. Accepts absolute paths, story-index-style relative paths with `./`, or relative paths without `./`. Pass an empty array to watch nothing (returns 0).'
              )
            )
          ),
        })
      ),
      output: v.number(),
      handler: (input, ctx) => {
        if (!input) {
          return ctx.self.state.graphRevision;
        }
        if (input.storyFiles.length === 0) {
          return 0;
        }

        let max = 0;
        const { workingDir } = ctx.self.state;
        for (const file of input.storyFiles) {
          const revision =
            ctx.self.state.storyChangeRevisions[toStoryIndexPath(file, workingDir)] ?? 0;
          if (revision > max) {
            max = revision;
          }
        }
        return max;
      },
    },
    latestStoryChanges: {
      description:
        'Latest story files whose module graph changed, paired with the graph revision that produced the change set.',
      input: noInputSchema,
      output: v.object({
        revision: v.pipe(
          v.number(),
          v.description('Graph revision number for this latest story change set.')
        ),
        storyFiles: v.pipe(
          v.array(storyIndexPathSchema),
          v.description(
            'Story-index-relative story files touched by the latest module graph change set.'
          )
        ),
      }),
      handler: (_input, ctx) => ({
        revision: ctx.self.state.graphRevision,
        storyFiles: ctx.self.state.latestChangedStoryFiles,
      }),
    },
    /** @deprecated Use {@link status} instead. */
    getStatus: {
      description: 'Deprecated alias for `status`. Use `status` instead.',
      input: noInputSchema,
      output: moduleGraphStatusSchema,
      handler: (input, ctx) => ctx.self.queries.status.get(input),
      load: async (input, ctx) => {
        await ctx.self.queries.status.loaded(input);
      },
    },
    /** @deprecated Use {@link graphRevision} instead. */
    getGraphRevision: {
      description: 'Deprecated alias for `graphRevision`. Use `graphRevision` instead.',
      input: v.optional(
        v.object({
          storyFiles: v.array(
            v.pipe(
              v.string(),
              v.description(
                'Story file to scope the watch to. Accepts absolute paths, story-index-style relative paths with `./`, or relative paths without `./`. Pass an empty array to watch nothing (returns 0).'
              )
            )
          ),
        })
      ),
      output: v.number(),
      handler: (input, ctx) => ctx.self.queries.graphRevision.get(input),
      load: async (input, ctx) => {
        await ctx.self.queries.graphRevision.loaded(input);
      },
    },
  },
  commands: {
    _applyGraphSnapshot: {
      internal: true,
      description:
        'Replaces the reverse index after the initial graph build. Called by the graph engine, not by external consumers.',
      input: v.object({
        storiesByFile: v.pipe(
          storiesByFileSchema,
          v.description(
            'Complete relative reverse index keyed by story-index-style source file paths. Values map affected story-index-style story file paths to breadth-first-search depths.'
          )
        ),
      }),
      output: v.void(),
      handler: async (input, ctx) => {
        ctx.self.setState((state) => {
          state.status = { value: 'ready' };
          state.storiesByFile = input.storiesByFile;
          // The snapshot is the baseline, not a change, so it does not advance the revision. Seed
          // every known story to revision 0 so scoped `graphRevision` reads track existing keys
          // and observe later per-story bumps.
          state.storyChangeRevisions = {};
          for (const stories of Object.values(input.storiesByFile)) {
            for (const storyFile of Object.keys(stories)) {
              state.storyChangeRevisions[storyFile] = 0;
            }
          }
          state.latestChangedStoryFiles = [];
        });
      },
    },
    _applyGraphUpdate: {
      internal: true,
      description:
        'Replaces the reverse index after an incremental patch and bumps versions for affected story files. Called by the graph engine, not by external consumers.',
      input: v.object({
        storiesByFile: v.pipe(
          storiesByFileSchema,
          v.description(
            'Complete relative reverse index keyed by story-index-style source file paths. Values map affected story-index-style story file paths to breadth-first-search depths.'
          )
        ),
        bumpedStoryFiles: v.pipe(
          v.array(storyIndexPathSchema),
          v.description(
            'Story files whose graph changed, using story-index-style relative paths. Each listed file has its version incremented.'
          )
        ),
      }),
      output: v.void(),
      handler: async (input, ctx) => {
        ctx.self.setState((state) => {
          state.storiesByFile = input.storiesByFile;
          // An out-of-graph file change recomputes the (unchanged) reverse index but bumps no
          // stories; it must not advance the revision, so watch-all and scoped subscribers stay put.
          if (input.bumpedStoryFiles.length === 0) {
            return;
          }
          state.graphRevision += 1;
          state.latestChangedStoryFiles = input.bumpedStoryFiles;
          for (const storyFile of input.bumpedStoryFiles) {
            state.storyChangeRevisions[storyFile] = state.graphRevision;
          }
        });
      },
    },
    _setStatus: {
      internal: true,
      description:
        'Sets the module graph lifecycle status after engine startup, failure, or adapter availability changes.',
      input: moduleGraphStatusSchema,
      output: v.void(),
      handler: async (input, ctx) => {
        ctx.self.setState((state) => {
          state.status = input as ModuleGraphServiceState['status'];
        });
      },
    },
    _waitForSettledEngine: {
      internal: true,
      description:
        'Starts the engine if needed and waits until its current build or patch cycle has finished. Handler is supplied at server registration.',
      input: noInputSchema,
      output: v.void(),
    },
  },
});

export type ModuleGraphService = ServiceInstanceOf<typeof moduleGraphServiceDef>;

