    await expect(publish).rejects.toBeInstanceOf(OpenServiceUnknownStoryIdsError);
    await expect(publish).rejects.toMatchObject({ data: { unknownIds: ['button--docs'] } });
    expect(service.queries.current.get(undefined)).toBeNull();
  });

