/**
 * The single implementation of react-docgen prop parsing, shared by the dev server and the hosted
 * `@storybook/mcp` package, which bundles this entry. Core does not depend on `react-docgen` /
 * `react-docgen-typescript`, so the type-only imports are the structural subsets the parsers
 * actually read rather than those packages' own types.
 */

/** Structural subset of react-docgen's `tsType` / `type` prop descriptor field. */
type TsType = {
  name?: string;
  raw?: string;
  value?: string;
  type?: string;
  elements?: TsType[];
  signature?: {
    arguments?: Array<{ name: string; type?: TsType }>;
    return?: TsType;
    properties?: Array<{ key: unknown; value?: TsType & { required?: boolean } }>;
  };
};

/** Structural subset of react-docgen's `Documentation` output. */
type Documentation = {
  props?: Record<
    string,
    {
      description?: string;
      required?: boolean;
      tsType?: TsType;
      type?: TsType;
      defaultValue?: { value?: string };
    }
  >;
};

type PropDescriptor = NonNullable<Documentation['props']>[string];

/** Structural subset of react-docgen-typescript's `ComponentDoc` output. */
type ComponentDoc = {
  props?: Record<
    string,
    {
      description?: string;
      required?: boolean;
      type?: { name?: string; raw?: string };
      defaultValue?: { value?: string } | null;
    }
  >;
};

export type ParsedDocgen = {
  props: Record<
    string,
    {
      description?: string;
      type?: string;
      defaultValue?: string;
      required?: boolean;
    }
  >;
};

// Storybook's `reactComponentMeta` payload is not the same full schema as
// `react-docgen-typescript`'s `ComponentDoc`, but `props` has the same type shape.
type ComponentDocLike = Pick<ComponentDoc, 'props'>;

// Serialize a react-docgen tsType into a TypeScript-like string when raw is not available
function serializeTsType(tsType: PropDescriptor['tsType']): string | undefined {
  if (!tsType) return undefined;
  // Prefer raw if provided
  if ('raw' in tsType && typeof tsType.raw === 'string' && tsType.raw.trim().length > 0) {
    return tsType.raw;
  }

  if (!tsType.name) return undefined;

  if ('elements' in tsType) {
    const serializeElements = () =>
      (tsType.elements ?? []).map((el: any) => serializeTsType(el) ?? 'unknown');

    switch (tsType.name) {
      case 'union':
        return serializeElements().join(' | ');
      case 'intersection':
        return serializeElements().join(' & ');
      case 'Array': {
        const inner = serializeTsType((tsType.elements ?? [])[0]) ?? 'unknown';
        return `${inner}[]`;
      }
      case 'tuple':
        return `[${serializeElements().join(', ')}]`;
    }
  }
  if ('value' in tsType && tsType.name === 'literal') {
    return tsType.value;
  }
  if ('signature' in tsType && tsType.name === 'signature') {
    if (tsType.type === 'function') {
      const args = (tsType.signature?.arguments ?? []).map((a: any) => {
        const argType = serializeTsType(a.type) ?? 'any';
        return `${a.name}: ${argType}`;
      });
      const ret = serializeTsType(tsType.signature?.return) ?? 'void';
      return `(${args.join(', ')}) => ${ret}`;
    }
    if (tsType.type === 'object') {
      const props = (tsType.signature?.properties ?? []).map((p) => {
        const req: boolean = Boolean(p.value?.required);
        const propType = serializeTsType(p.value) ?? 'any';
        return `${p.key as string}${req ? '' : '?'}: ${propType}`;
      });
      return `{ ${props.join('; ')} }`;
    }
    return 'unknown';
  }
  // Default case (Generic like Item<TMeta>)
  if ('elements' in tsType) {
    const inner = (tsType.elements ?? []).map((el) => serializeTsType(el) ?? 'unknown');
    if (inner.length > 0) return `${tsType.name}<${inner.join(', ')}>`;
  }

  return tsType.name;
}

export const parseReactDocgen = (reactDocgen: Documentation): ParsedDocgen => {
  const props: Record<string, any> = (reactDocgen as any)?.props ?? {};
  return {
    props: Object.fromEntries(
      Object.entries(props).map(([propName, prop]) => [
        propName,
        {
          description: prop.description,
          type: serializeTsType(prop.tsType ?? prop.type),
          defaultValue: prop.defaultValue?.value,
          required: prop.required,
        },
      ])
    ),
  };
};

/**
 * Parse react-docgen-typescript output into the same simplified ParsedDocgen format.
 * RDT uses flat type strings (prop.type.name / prop.type.raw) instead of react-docgen's
 * nested tsType structure, so no serialization is needed.
 */
const parseComponentDocLike = (componentDoc: ComponentDocLike): ParsedDocgen => {
  const props = componentDoc.props ?? {};
  return {
    props: Object.fromEntries(
      Object.entries(props).map(([propName, prop]) => [
        propName,
        {
          description: prop.description || undefined,
          // RDT uses prop.type.name as a flat string (e.g. "() => void", "{ id: string }")
          // For enums, prefer prop.type.raw which has the full union
          type: prop.type?.raw ?? prop.type?.name,
          defaultValue: prop.defaultValue?.value,
          required: prop.required,
        },
      ])
    ),
  };
};

export const parseReactDocgenTypescript = (reactDocgenTypescript: ComponentDoc): ParsedDocgen =>
  parseComponentDocLike(reactDocgenTypescript);

export const parseReactComponentMeta = (reactComponentMeta: ComponentDocLike): ParsedDocgen =>
  parseComponentDocLike(reactComponentMeta);

/** Maps `items` with at most `limit` concurrent in-flight `fn` calls. */
export async function mapWithConcurrency<T, R>(
  items: readonly T[],
  limit: number,
  fn: (item: T, index: number) => Promise<R>
): Promise<R[]> {
  if (items.length === 0) {
    return [];
  }

  // Guard against a non-finite `limit` (e.g. NaN), which would otherwise make `concurrency` NaN
  // and spawn zero workers, leaving results unfilled.
  const safeLimit = Number.isFinite(limit) ? limit : items.length;
  const concurrency = Math.max(1, Math.min(safeLimit, items.length));
  const results = Array<R>(items.length);
  let nextIndex = 0;

  async function worker(): Promise<void> {
    while (nextIndex < items.length) {
      const index = nextIndex++;
      results[index] = await fn(items[index]!, index);
    }
  }

  await Promise.all(Array.from({ length: concurrency }, () => worker()));
  return results;
}

import type { DocsClassification } from './classify-services.ts';

export type MdxDoc = {
  id: string;
  name: string;
  path?: string;
  title?: string;
  content?: string;
  summary?: string;
  error?: { name: string; message: string };
};

export type MdxPayload = {
  id: string;
  name: string;
  docs: Record<string, MdxDoc>;
};

/**
 * Picks a component's attached MDX docs out of its payload, shared by the Markdown and JSON docs
 * paths so the two cannot drift. `undefined` when the component has no attached docs, letting
 * callers omit the key entirely.
 */
export function selectAttachedDocs(
  classification: DocsClassification,
  id: string,
  mdx: MdxPayload | undefined
): Record<string, MdxDoc> | undefined {
  const attached = classification.attachedDocsByComponent.get(id) ?? [];
  if (attached.length === 0 || !mdx?.docs) {
    return undefined;
  }

  const docs: Record<string, MdxDoc> = {};
  for (const docsId of attached) {
    const doc = mdx.docs[docsId];
    if (doc) {
      docs[docsId] = doc;
    }
  }
  return docs;
}

/**
 * How a composition picks the access for each of its sources.
 *
 * The local Storybook is a source like any other, but it is the one this process can read directly.
 * These tests pin that routing, so a composition cannot quietly grow a second way of reading the
 * Storybook it is already serving.
 */

import { describe, expect, it, vi } from 'vitest';

import type { DocsAccess } from './access.ts';
import { createCompositionDocsSources } from './multi-source.ts';

const LOCAL = { id: 'local', title: 'Local' };
const REMOTE = { id: 'design-system', title: 'Design System', url: 'https://ds.example.com' };

/** Serves a minimal but valid pair of manifests, whatever path is asked for. */
function providerStub() {
  return vi.fn(async (_request: unknown, path: string) =>
    path.endsWith('docs.json')
      ? '{"v":1,"docs":{}}'
      : '{"v":1,"components":{"a":{"id":"a","name":"A"}}}'
  );
}

function accessStub(): DocsAccess {
  return {
    list: vi.fn().mockResolvedValue({ componentManifest: { v: 1, components: {} } }),
    resolve: vi.fn().mockResolvedValue(undefined),
  };
}

describe('createCompositionDocsSources', () => {
  it('reads the local source through the access it was given', async () => {
    const localAccess = accessStub();
    const manifestProvider = vi.fn();

    const [local] = createCompositionDocsSources({
      sources: [LOCAL],
      localAccess,
      manifestProvider,
    });

    await local!.access.list({ withStoryIds: false });

    expect(localAccess.list).toHaveBeenCalled();
    expect(manifestProvider).not.toHaveBeenCalled();
  });

  it('still fetches remote sources over the provider when a local access is given', async () => {
    const localAccess = accessStub();
    const manifestProvider = providerStub();

    const sources = createCompositionDocsSources({
      sources: [LOCAL, REMOTE],
      localAccess,
      manifestProvider,
    });
    const remote = sources.find(({ source }) => source.id === REMOTE.id)!;

    await remote.access.list({ withStoryIds: false });

    expect(manifestProvider).toHaveBeenCalled();
    expect(localAccess.list).not.toHaveBeenCalled();
  });

  it('falls back to the provider for the local source when no access is given', async () => {
    const manifestProvider = providerStub();

    const [local] = createCompositionDocsSources({ sources: [LOCAL], manifestProvider });
    await local!.access.list({ withStoryIds: false });

    expect(manifestProvider).toHaveBeenCalled();
  });
});

/**
 * Composition support for the docs toolset.
 *
 * A composed Storybook is not a different kind of docs engine — it is several of the same one. So
 * composition is modelled as a set of {@link DocsAccess} instances, one per source, rather than a
 * parallel implementation: whatever backs a single Storybook (manifests over HTTP, the open
 * services in-process) backs one source of a composition unchanged.
 *
 * What composition does add is per-source failure isolation when listing; routing a lookup to the
 * source the caller named is the toolset's job, since only it knows how to explain a bad id.
 */

import { createProviderDocsAccess, type ManifestProvider } from './access-provider.ts';
import type { DocsAccess, ResolvedDocsEntry } from './access.ts';
import {
  ManifestGetError,
  RequiresOwnMcpError,
  type Source,
  type SourceListing,
} from './sources.ts';

/** One composed source and the access that reads it. */
export type DocsSource = {
  source: Source;
  access: DocsAccess;
};

export type CompositionDocsSourcesOptions = {
  sources: Source[];
  manifestProvider?: ManifestProvider;
  getRequest?: () => Request | undefined;
  /**
   * Reads the local Storybook — the source with no `url` — instead of fetching manifests from it.
   * The dev server passes its service-backed access here when `experimentalDocgenServer` is on,
   * where the local `/manifests/*.json` are deliberately 404'd and the data lives in the services.
   */
  localAccess?: DocsAccess;
  /**
   * Resolves a single entry in-process, short-cutting the manifest index. Part of the hosted
   * package's public context, so it stays available to embedders that supply one.
   */
  resolveEntry?: (id: string, source?: Source) => Promise<ResolvedDocsEntry | undefined>;
};

/**
 * Builds one access per composed source.
 *
 * Remote sources are read through the same provider access a single hosted Storybook uses, which is
 * what lets a composition reuse that implementation rather than a parallel one. The local source
 * may instead be handed a ready-made access, so the dev server reads itself the same way in a
 * composition as it does alone.
 */
export function createCompositionDocsSources({
  sources,
  manifestProvider,
  getRequest,
  localAccess,
  resolveEntry,
}: CompositionDocsSourcesOptions): DocsSource[] {
  return sources.map((source) => ({
    source,
    access:
      localAccess && !source.url
        ? localAccess
        : createProviderDocsAccess({ source, manifestProvider, getRequest, resolveEntry }),
  }));
}

/**
 * Lists every source concurrently, turning a failure into that source's own outcome.
 *
 * One unreachable or private source must not cost the agent the entire listing, which is the whole
 * reason each result is captured rather than awaited together.
 */
export async function listSources(
  sources: DocsSource[],
  options: { withStoryIds: boolean }
): Promise<SourceListing[]> {
  const listings = await Promise.all(
    sources.map(async ({ source, access }): Promise<SourceListing> => {
      try {
        return { source, manifests: await access.list(options) };
      } catch (error) {
        if (error instanceof RequiresOwnMcpError) {
          return { source, notice: { kind: 'requires-own-mcp', endpoint: error.endpoint } };
        }
        return { source, error: error instanceof Error ? error.message : String(error) };
      }
    })
  );

  // Isolation is only worth it while something still reads. If no source produced output at all,
  // a page of repeated errors buries the reason, so report the failure itself.
  const usable = listings.filter((listing) => !listing.error);
  if (usable.length === 0) {
    throw new ManifestGetError(
      `Failed to fetch manifests from any source. Errors:\n${listings
        .map((listing) => `- ${listing.source.title}: ${listing.error}`)
        .join('\n')}`
    );
  }

  return listings;
}

/**
 * Guards the portable d.ts artifact of the `storybook/internal/toolsets-docs` entry.
 *
 * `@storybook/mcp` bundles this entry's declarations into its own dist through standard module
 * resolution, so the artifact must be one flat self-contained file whose only external imports are
 * on that package's own dependency list. An edit that entangles the entry with react, another core
 * surface, or a shared type chunk must fail here — where the artifact is produced — with a message
 * naming the offending import, not in a consumer's build.
 *
 * Deliberately reads the real built artifact (no memfs): the guarded property is what the build
 * actually wrote to disk.
 */

import { existsSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';

import { describe, expect, it } from 'vitest';

const DTS_ARTIFACT = join(
  import.meta.dirname,
  '../../../../../dist/shared/open-service/toolsets/docs/public.d.ts'
);

/**
 * The only module specifiers the flat file may reference.
 *
 * Deliberately a copy of the entry's `portable.external` in `build-config.ts`, not derived from
 * it: every allowed import is a dependency each consumer must declare, so widening the list has to
 * be a reviewer-visible edit here rather than something the config change passes silently.
 */
const IMPORT_ALLOWLIST = ['valibot'];

/**
 * Headroom over the current size (~64 KB), so ordinary edits pass but a bundling regression does
 * not — the shared-chunk entanglement this pass exists to prevent once pulled in ~904 KB.
 */
const SIZE_BUDGET_BYTES = 100_000;

/**
 * Every syntactic position that references another module in a d.ts: static `from`, dynamic
 * `import(...)` type references, `require(...)`, side-effect `import "..."`, and ambient
 * `declare module "..."` augmentation.
 */
const MODULE_SPECIFIER_RE =
  /(?:\bfrom\s*|\bimport\s*\(\s*|\brequire\s*\(\s*|\bimport\s+|\bmodule\s+)["']([^"']+)["']/g;

/**
 * Triple-slash directives (`/// <reference types|path|lib="..." />`) pull in declarations outside
 * the import syntax above, so their targets count as specifiers too: a `path` reference breaks
 * flatness and a `types`/`lib` reference must pass the allowlist like any import.
 */
const REFERENCE_DIRECTIVE_RE = /^\/\/\/\s*<reference\s+(?:types|path|lib)\s*=\s*["']([^"']+)["']/gm;

function readSpecifiers(): string[] {
  const source = readFileSync(DTS_ARTIFACT, 'utf-8');
  return [...source.matchAll(MODULE_SPECIFIER_RE), ...source.matchAll(REFERENCE_DIRECTIVE_RE)].map(
    (match) => match[1]
  );
}

/**
 * The dist-reading assertions are skipped on a working copy that has not been production-built,
 * which would make them pass vacuously in CI — where a build always precedes the tests. So there,
 * the artifact's absence is the failure.
 */
const DTS_BUILT = existsSync(DTS_ARTIFACT);

describe('portable toolsets-docs declarations', () => {
  it.runIf(process.env.CI)('are built before this suite runs', () => {
    expect(DTS_BUILT).toBe(true);
  });

  it.runIf(DTS_BUILT)('are one flat file: no relative imports', () => {
    expect(readSpecifiers().filter((specifier) => specifier.startsWith('.'))).toEqual([]);
  });

  it.runIf(DTS_BUILT)('import exactly the allowlist', () => {
    expect([...new Set(readSpecifiers())].sort()).toEqual(IMPORT_ALLOWLIST);
  });

  it.runIf(DTS_BUILT)('stay within their size budget', () => {
    expect(statSync(DTS_ARTIFACT).size).toBeLessThan(SIZE_BUDGET_BYTES);
  });
});

