/**
 * Composed Storybook sources.
 *
 * A composition serves several Storybooks through one MCP endpoint: the local one plus every
 * `refs` entry. Each source is read independently, so one unreachable or private source degrades
 * to a message in its own section rather than failing the whole listing.
 */

import type { AllManifests } from './manifest-formatter/manifest-types.ts';

/** One Storybook in a composition. The local source has no `url`. */
export type Source = {
  /** Stable identifier, used as the `storybookId` tool input. */
  id: string;
  /** Human-readable title, used as the section header when listing. */
  title: string;
  /** Remote URL; undefined for the local Storybook. */
  url?: string;
};

export type SourceWithUrl = Source & { url: string };

/** Guidance for a source that can only be read through its own MCP endpoint. */
export type RequiresOwnMcpNotice = {
  kind: 'requires-own-mcp';
  endpoint: string;
};

/**
 * One source's contribution to a composed listing. Exactly one of `manifests`, `error` or `notice`
 * carries the outcome, so a failing source occupies its own section instead of the whole listing.
 */
export type SourceListing = {
  source: Source;
  manifests?: AllManifests;
  error?: string;
  notice?: RequiresOwnMcpNotice;
};

export function getSourceMcpEndpoint(source: SourceWithUrl): string {
  const base = new URL(source.url);
  base.pathname = `${base.pathname.replace(/\/$/, '')}/`;
  return new URL('mcp', base).toString();
}

/**
 * A private composed Storybook cannot be proxied — its credentials belong to the user, not to this
 * server — so the answer is the address the agent should talk to instead.
 */
export function formatRequiresOwnMcpNotice(
  source: Source,
  endpoint: string,
  options: { includeHeader?: boolean } = {}
): string {
  const parts: string[] = [];

  if (options.includeHeader ?? true) {
    parts.push(`# ${source.title}`);
    parts.push(`id: ${source.id}`);
    parts.push('');
  }

  parts.push(
    'This composed Storybook is private and cannot be read through the local Storybook MCP proxy.'
  );
  parts.push('');
  parts.push("Use this source's own MCP endpoint instead:");
  parts.push(endpoint);

  return parts.join('\n');
}

export class RequiresOwnMcpError extends Error {
  public readonly source: SourceWithUrl;
  public readonly endpoint: string;

  constructor(source: SourceWithUrl) {
    const endpoint = getSourceMcpEndpoint(source);
    super(`Composed Storybook "${source.title}" requires its own MCP endpoint: ${endpoint}`);
    this.name = 'RequiresOwnMcpError';
    this.source = source;
    this.endpoint = endpoint;
  }
}

/** Thrown when a manifest cannot be fetched or does not parse. */
export class ManifestGetError extends Error {
  public readonly url: string;
  public override readonly cause?: Error;

  constructor(message: string, url?: string, cause?: Error) {
    super(message);
    this.name = 'ManifestGetError';
    this.url = url ?? 'No source URL provided';
    this.cause = cause;
  }
}

import { describe, it, expect } from 'vitest';
import { estimateTokens } from './estimate-tokens.ts';

describe('estimateTokens', () => {
  it('should return 0 for empty string', () => {
    expect(estimateTokens('')).toBe(0);
  });

  it('should count single word', () => {
    expect(estimateTokens('hello')).toBe(1);
  });

  it('should count words separated by single space', () => {
    expect(estimateTokens('hello world')).toBe(3); // hello + space + world
  });

  it('should count multiple continuous spaces as single token', () => {
    expect(estimateTokens('hello   world')).toBe(3); // hello + multiple-spaces + world
  });

  it('should count tabs and newlines as single whitespace token', () => {
    expect(estimateTokens('hello\t\nworld')).toBe(3); // hello + tab-newline + world
  });

  it('should count hyphenated words separately', () => {
    expect(estimateTokens('hello-world')).toBe(3); // hello + hyphen + world
  });

  it('should count continuous special characters individually', () => {
    expect(estimateTokens('hello---world')).toBe(5); // hello + - + - + - + world
  });

  it('should count punctuation individually', () => {
    expect(estimateTokens('hello, world!')).toBe(5); // hello + comma + space + world + exclamation
  });

  it('should handle leading and trailing whitespace', () => {
    expect(estimateTokens('  hello world  ')).toBe(5); // leading-spaces + hello + space + world + trailing-spaces
  });

  it('should count complex text correctly', () => {
    const text = `# Getting Started

Welcome to the component library.`;
    // # + space + Getting + space + Started + double-newline + Welcome + space + to + space + the + space + component + space + library + .
    const result = estimateTokens(text);
    expect(result).toBe(16);
  });

  it('should handle code examples with punctuation and symbols', () => {
    const text = 'const x = 123;';
    // const + space + x + space + = + space + 123 + ;
    expect(estimateTokens(text)).toBe(8);
  });

  it('should count URLs correctly', () => {
    const text = 'https://example.com/path';
    // https + : + / + / + example + . + com + / + path
    expect(estimateTokens(text)).toBe(9);
  });
});

/**
 * Checks if a character code is whitespace (space, tab, newline, carriage return)
 *
 * Checking char codes is slightly faster than using regex or string methods.
 */
function isWhitespace(code: number): boolean {
  return code === 32 || code === 9 || code === 10 || code === 13;
}

/**
 * Checks if a character code is alphanumeric or underscore
 * 0-9 (48-57), A-Z (65-90), a-z (97-122), underscore (95)
 *
 * Checking char codes is slightly faster than using regex or string methods.
 */
function isAlphanumeric(code: number): boolean {
  return (
    (code >= 48 && code <= 57) ||
    (code >= 65 && code <= 90) ||
    (code >= 97 && code <= 122) ||
    code === 95
  );
}

/**
 * Estimates token count from text using a fast approximation.
 * Counts:
 * - Continuous whitespace as a single token
 * - Continuous alphanumeric sequences as single tokens
 * - Each special character as an individual token
 *
 * This is a cheap approximation suitable for telemetry purposes.
 *
 * @param text - The text to estimate token count for
 * @returns Estimated token count
 */
export function estimateTokens(text: string): number {
  if (!text) return 0;

  let tokenCount = 0;
  let i = 0;
  const len = text.length;

  while (i < len) {
    const code = text.charCodeAt(i);

    if (isWhitespace(code)) {
      tokenCount++;
      i++;
      while (i < len && isWhitespace(text.charCodeAt(i))) {
        i++;
      }
    } else if (isAlphanumeric(code)) {
      tokenCount++;
      i++;
      while (i < len && isAlphanumeric(text.charCodeAt(i))) {
        i++;
      }
    } else {
      tokenCount++;
      i++;
    }
  }

  return tokenCount;
}

