      results: [
        {
          matches: [
            expect.objectContaining({ storyId: 'button--primary' }),
            expect.objectContaining({ storyId: 'button--secondary' }),
          ],
          clipped: { count: 1, distances: [DEFAULT_MAX_DISTANCE + 1] },
        },
      ],
    });
