    const locked = path.join(FAKE_WORKING_DIR, 'src/components/Locked/Locked.tsx');
    vi.mocked(realpathSync.native).mockImplementation((filePath) => {
      if (asGraphPath(String(filePath)) === asGraphPath(locked)) {
        throw Object.assign(new Error(`EACCES: ${locked}`), { code: 'EACCES' });
      }
      return String(vol.realpathSync(filePath));
    });
    await expect(resolveComponentStories({ componentPaths: [locked] }, depsFor())).rejects.toThrow(
      /EACCES/
    );
  });

  it('returns available:false when the module graph service is not registered', async () => {
    const res = await resolveComponentStories(
      { componentPaths: [BADGE_ABS] },
      { ...depsFor(), moduleGraph: undefined }
    );
    expect(res.available).toBe(false);
    expect(res.reason).toMatch(/module graph is unavailable/i);
    expect(res.results).toBeUndefined();
  });

  it('returns available:false while the graph is still booting', async () => {
    const res = await resolveComponentStories(
      { componentPaths: [BADGE_ABS] },
      depsFor({}, moduleGraphStub({ status: { value: 'booting' } }))
    );
    expect(res.available).toBe(false);
    expect(res.reason).toMatch(/hasn't built yet/i);
  });

  it('returns available:false with the remedy the agent needs when unavailable', async () => {
    const res = await resolveComponentStories(
      { componentPaths: [BADGE_ABS] },
      depsFor(
        {},
        moduleGraphStub({
          status: { value: 'unavailable', reason: 'builder does not support change detection' },
        })
      )
    );
    expect(res.available).toBe(false);
    // The service's cause plus the remedy: the agent is told what failed and what to change.
    expect(res.reason).toBe(
      "Storybook's story dependency graph is unavailable: builder does not support change detection. Make sure the dev server is running with a builder that supports change detection."
    );
  });

  it('returns available:false with the serialized error message when the graph errored', async () => {
    const res = await resolveComponentStories(
      { componentPaths: [BADGE_ABS] },
      depsFor(
        {},
        moduleGraphStub({ status: { value: 'error', error: { message: 'boom while parsing' } } })
      )
    );
    expect(res.available).toBe(false);
    expect(res.reason).toMatch(/boom while parsing/);
  });
});

import { existsSync, realpathSync } from 'node:fs';

import type { StoryIndex } from 'storybook/internal/types';

import { basename, dirname, extname, join, normalize, resolve } from 'pathe';

import type { ModuleGraphServiceState } from '../../services/module-graph/definition.ts';

/** Lifecycle status reported by the `core/module-graph` service. */
export type ModuleGraphStatus = ModuleGraphServiceState['status'];

/** One reverse-index hit: a story file (story-index-relative path) and its BFS import depth. */
export type ModuleGraphStoryHit = {
  /** Story-index-style relative path such as `./src/Button.stories.tsx`. */
  storyFile: string;
  /** Breadth-first-search depth: shortest number of import edges to the story file. */
  depth: number;
};

/**
 * The slice of the `core/module-graph` service this resolver needs. Structural so the caller can
 * inject the real service (or a stub) without this module doing service lookup itself.
 */
export type ModuleGraphAccess = {
  queries: {
    status: { loaded: (input?: undefined) => Promise<ModuleGraphStatus> };
    /** Positional: result `i` corresponds to input `files[i]`. */
    storiesForFiles: {
      loaded: (input: { files: string[] }) => Promise<Array<ModuleGraphStoryHit[] | undefined>>;
    };
  };
};

const SOURCE_EXTENSIONS = ['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs'] as const;
const INDEX_BASENAMES = SOURCE_EXTENSIONS.map((ext) => `index${ext}`);

/** Storybook import paths always use forward slashes, even on Windows. */
function slash(filePath: string): string {
  return filePath.replace(/\\/g, '/');
}

/**
 * Expands `Foo/Foo.tsx` ↔ `Foo/index.tsx` so a query against either form hits stories that
 * imported the other. Only expands when filename or dirname clearly names the directory's
 * main export.
 */
function expandBarrelTargets(absoluteComponentPath: string): string[] {
  const targets = new Set<string>([absoluteComponentPath]);
  const dir = dirname(absoluteComponentPath);
  const ext = extname(absoluteComponentPath);
  const base = basename(absoluteComponentPath, ext);
  const dirName = basename(dir);

  if (base.toLowerCase() === 'index') {
    for (const candidateExt of SOURCE_EXTENSIONS) {
      const candidate = join(dir, `${dirName}${candidateExt}`);
      if (existsSync(candidate)) {
        targets.add(candidate);
      }
    }
  } else if (base.toLowerCase() === dirName.toLowerCase()) {
    for (const indexBasename of INDEX_BASENAMES) {
      const candidate = join(dir, indexBasename);
      if (existsSync(candidate)) {
        targets.add(candidate);
      }
    }
  }

  // The module graph accepts absolute paths but normalizes them with forward slashes; `pathe`'s
  // `normalize` emits forward slashes on Windows too, including for `realpath` output.
  return [...targets].map((target) => normalize(target));
}

/**
 * Canonicalises a path via `realpath`. Fixes silent misses on case-insensitive filesystems
 * (macOS APFS) where `BUTTON/Button.tsx` and `Button/Button.tsx` resolve to the same file but
 * only the canonical form is in the reverse-index keyset.
 *
 * Returns `undefined` if the path doesn't exist on disk — the caller surfaces that as a
 * distinct "path not found" outcome rather than a generic "no stories".
 */
function canonicalise(absolutePath: string): string | undefined {
  try {
    return realpathSync.native(absolutePath);
  } catch (err) {
    // Only a missing path is "not found"; permission/IO errors are real failures and must not be
    // silently misreported as `pathNotFound`, so rethrow anything that isn't ENOENT.
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
      return undefined;
    }
    throw err;
  }
}

/**
 * Normalizes a story-index `importPath` to the `./`-prefixed, forward-slash form the module graph
 * returns for its story files (e.g. `./src/Button.stories.tsx`). The module graph keys story files
 * this way, so we match on it instead of the absolute path.
 */
function toStoryFileKey(importPath: string): string {
  const normalized = slash(importPath);
  if (normalized.startsWith('./') || normalized.startsWith('../')) {
    return normalized;
  }
  return `./${normalized}`;
}

/**
 * Map story-index-relative story-file path → story IDs declared in that file. Skips virtual entries.
 * Keys match the `storyFile` values returned by the module graph's `storiesForFiles`.
 */
function buildStoryIdsByFile(storyIndex: StoryIndex): Map<string, Set<string>> {
  const storyIdsByFile = new Map<string, Set<string>>();
  for (const entry of Object.values(storyIndex.entries)) {
    if (entry.type !== 'story' || entry.importPath.startsWith('virtual:')) {
      continue;
    }
    const filePath = toStoryFileKey(entry.importPath);
    let ids = storyIdsByFile.get(filePath);
    if (!ids) {
      ids = new Set<string>();
      storyIdsByFile.set(filePath, ids);
    }
    ids.add(entry.id);
  }
  return storyIdsByFile;
}

/** Builds the unavailable reason for a non-`ready` module-graph status. */
export function reasonForStatus(status: ModuleGraphStatus): string {
  switch (status.value) {
    case 'booting':
      return "Storybook's story module graph hasn't built yet — it is still being constructed. Retry shortly.";
    case 'unavailable':
      // The service's own reason names the adapter-specific cause; the remedy sentence stays
      // appended because the agent's next move is to check how the dev server runs, which that
      // reason does not say.
      return `Storybook's story dependency graph is unavailable: ${status.reason}. Make sure the dev server is running with a builder that supports change detection.`;
    case 'error':
      return `Storybook's story module graph failed to build: ${status.error.message}`;
    case 'ready':
      return "Storybook's story module graph is ready.";
    default: {
      const exhaustive: never = status;
      return exhaustive;
    }
  }
}

export interface ComponentStoriesRequest {
  componentPaths: string[];
}

export interface ComponentStoryDepth {
  storyId: string;
  depth: number;
}

export interface ComponentStoriesResult {
  /** Echoes the caller's input path, lightly normalized (redundant separators etc. collapsed). */
  componentPath: string;
  matches: ComponentStoryDepth[];
  /** `true` when no file exists at the resolved absolute path — distinguishes "typo" from "no stories yet". */
  pathNotFound?: boolean;
}

export interface ComponentStoriesResponse {
  available: boolean;
  reason?: string;
  results?: ComponentStoriesResult[];
}

export interface ResolveComponentStoriesDeps {
  /** Live story index; injectable so tests can pin a fixed value. */
  getStoryIndex: () => Promise<StoryIndex>;
  /**
   * The `core/module-graph` service, or `undefined` when it isn't registered in this process (e.g.
   * a builder without change detection, or an older Storybook without the open-service API).
   */
  moduleGraph: ModuleGraphAccess | undefined;
  /** Defaults to `process.cwd()`, matching the dev server. */
  workingDir?: string;
}

/** Per-component target set, resolved before the batched module-graph lookup. */
interface ResolvedComponent {
  /** Cleaned-up echo of the caller's input path. */
  componentPath: string;
  /** Forward-slashed absolute target paths (barrel-expanded) to look up. */
  targets: string[];
  pathNotFound?: boolean;
}

/**
 * Looks up stories that consume each component path via Storybook's `core/module-graph` reverse
 * index. Returns `{ available: false }` when the graph isn't ready; otherwise per-path results.
 *
 * The unavailable/booting/error cases are reported rather than flattened into "no matches" so a
 * caller can't mistake an unsupported builder or a still-booting graph for "this component is
 * unused".
 */
export async function resolveComponentStories(
  request: ComponentStoriesRequest,
  deps: ResolveComponentStoriesDeps
): Promise<ComponentStoriesResponse> {
  const { moduleGraph } = deps;
  if (!moduleGraph) {
    return {
      available: false,
      reason:
        "Storybook's story module graph is unavailable. This Storybook version may not ship the open-service API, the module-graph service isn't registered (e.g. a builder without change detection), or the dev server is not running.",
    };
  }

  // `status.loaded` awaits the graph's settle barrier, so by the time it resolves the status is
  // no longer `booting` unless the graph genuinely never built — handle every non-ready case.
  const status = await moduleGraph.queries.status.loaded(undefined);
  if (status.value !== 'ready') {
    return { available: false, reason: reasonForStatus(status) };
  }

  const workingDir = deps.workingDir ?? process.cwd();
  const storyIndex = await deps.getStoryIndex();
  const storyIdsByFile = buildStoryIdsByFile(storyIndex);

  // Dedupe inputs so an agent that grep'd loosely doesn't get the same component echoed back twice.
  const deduped = [...new Set(request.componentPaths)];

  // Phase 1: resolve each component to its expanded set of target paths.
  const resolved: ResolvedComponent[] = deduped.map((componentPath) => {
    // Normalize first: a trailing slash on `/abs/Badge/Badge.tsx/` would otherwise flip the
    // barrel-expansion heuristic and silently return barrel consumers instead of the file.
    const absolute = resolve(workingDir, componentPath);
    const canonical = canonicalise(absolute);

    // Echo a cleaned-up form of the input (no redundant separators / `..` segments) rather than the
    // raw string. Keeps relative paths relative and absolute paths absolute.
    const echo = normalize(componentPath);

    if (!canonical) {
      return { componentPath: echo, targets: [], pathNotFound: true };
    }

    // Include both the input's normalized form and the canonical form. On case-insensitive
    // filesystems they differ when the caller passed a wrong-case path; using both means we hit
    // the graph regardless of which form the caller supplied.
    const targets = new Set<string>(expandBarrelTargets(absolute));
    if (canonical !== absolute) {
      for (const target of expandBarrelTargets(canonical)) {
        targets.add(target);
      }
    }

    return { componentPath: echo, targets: [...targets] };
  });

  // Phase 2: one batched reverse-index lookup over the union of every component's targets.
  const allTargets = [...new Set(resolved.flatMap((component) => component.targets))];
  const hitsByTarget = new Map<string, ModuleGraphStoryHit[]>();
  if (allTargets.length > 0) {
    const batched = await moduleGraph.queries.storiesForFiles.loaded({ files: allTargets });
    // Output is positional: result `i` corresponds to input `allTargets[i]`.
    allTargets.forEach((target, i) => {
      hitsByTarget.set(target, batched[i] ?? []);
    });
  }

  // Phase 3: merge hits back per component, keeping the minimum depth per storyId.
  const results: ComponentStoriesResult[] = resolved.map((component) => {
    if (component.pathNotFound) {
      return { componentPath: component.componentPath, matches: [], pathNotFound: true };
    }

    const byStoryId = new Map<string, number>();
    for (const target of component.targets) {
      const hits = hitsByTarget.get(target) ?? [];
      for (const { storyFile, depth } of hits) {
        const storyIds = storyIdsByFile.get(storyFile);
        if (!storyIds) {
          continue;
        }
        for (const storyId of storyIds) {
          const existing = byStoryId.get(storyId);
          if (existing === undefined || depth < existing) {
            byStoryId.set(storyId, depth);
          }
        }
      }
    }

    const matches: ComponentStoryDepth[] = [...byStoryId.entries()]
      .map(([storyId, depth]) => ({ storyId, depth }))
      .sort((a, b) => {
        if (a.depth !== b.depth) {
          return a.depth - b.depth;
        }
        return a.storyId.localeCompare(b.storyId);
      });

    return { componentPath: component.componentPath, matches };
  });

  return { available: true, results };
}

import * as v from 'valibot';

import { toMcpToolName } from '../../toolset-names.ts';

/**
 * Per-shape props/globals selectors, shared by both story selector variants.
 *
 * The prose predates the toolsets and is eval-tuned, so it is kept verbatim. It names sibling
 * capabilities by their MCP tool names rather than through `getToolName`, because valibot descriptions
 * are static strings with no per-consumer rendering. One of them, `get-storybook-story-instructions`,
 * is an `@storybook/addon-mcp` tool with no toolset method;
 * a CLI consumer would need this sentence rewritten rather than re-rendered.
 */
const storyInputProps = {
  props: v.pipe(
    v.optional(v.record(v.string(), v.any())),
    v.description(`Optional custom props to pass to the story for rendering. Use this when you don't want to render the default story,
but you want to customize some args or other props.
You can look up the component's documentation using the get-storybook-story-instructions tool to see what props are available.`)
  ),
  globals: v.pipe(
    v.optional(v.record(v.string(), v.any())),
    v.description(`Optional Storybook globals to set for the story preview. Globals are used for things like theme, locale, viewport, and other cross-cutting concerns.
Common globals include 'theme' (e.g., 'dark', 'light'), 'locale' (e.g., 'en', 'fr'), and 'backgrounds' (e.g., { value: '#000' }).`)
  ),
};

/**
 * Shared story selector used by the stories and test APIs.
 *
 * Prefer `{ storyId }` unless the caller already has a concrete story-file path and export name.
 */
export const storyInputSchema = v.union([
  v.object({
    exportName: v.pipe(
      v.string(),
      v.description(
        `The export name of the story from the story file.
Use this path-based shape only when you're already editing a .stories.* file and know the export names in that file.
If you do not already have story file context, prefer the storyId shape instead of searching files.`
      )
    ),
    explicitStoryName: v.pipe(
      v.optional(v.string()),
      v.description(
        `If the story has an explicit name set via the "name" property, that is different from the export name, provide it here.
Otherwise don't set this.`
      )
    ),
    absoluteStoryPath: v.pipe(
      v.string(),
      v.description(
        'Absolute path to the story file. Use together with exportName only when story file context is already available.'
      )
    ),
    ...storyInputProps,
  }),
  v.object({
    storyId: v.pipe(
      v.string(),
      v.description(
        `The full Storybook story ID (for example "button--primary").
Prefer this shape whenever you are not already working in a specific story file.
Use IDs discovered from ${toMcpToolName('docs.list')} (withStoryIds=true) or ${toMcpToolName('docs.show')}.`
      )
    ),
    ...storyInputProps,
  }),
]);

export const storyInputArraySchema = v.array(storyInputSchema);

export type StoryInput = v.InferOutput<typeof storyInputSchema>;

import { logger } from 'storybook/internal/node-logger';

import { resolve as resolvePath } from 'pathe';

import type { ModuleGraphService } from '../../services/module-graph/definition.ts';
import type { StoriesGitAccess } from './definition.ts';

const SOURCE_EXT_RE = /\.(?:tsx?|jsx?|mjs|cjs)$/i;

/**
 * Module-graph query batch size. Bounds the per-call file list so a large working tree doesn't
 * issue one oversized reverse-index query; we early-exit between chunks once `maxFiles` is reached.
 */
const CHUNK_SIZE = 50;

/** Cap on files reported inline, so a large working tree can't dominate the response. */
const DEFAULT_MAX_FILES = 10;

/**
 * Lists working-tree files that no story reaches through the import graph.
 *
 * This is the "your edit isn't in the graph; you'll need to grep" case — typical for theme tokens,
 * decorator config, and other files consumed through Storybook's preview runtime rather than a
 * story-file import. Paths stay repo-root-relative because they are shown to an agent that will
 * grep for them.
 */
export async function detectUnreachableFiles({
  git,
  moduleGraph,
  maxFiles = DEFAULT_MAX_FILES,
}: {
  git: StoriesGitAccess;
  moduleGraph: ModuleGraphService;
  maxFiles?: number;
}): Promise<string[]> {
  const status = await moduleGraph.queries.status.loaded(undefined);
  if (status.value !== 'ready') {
    return [];
  }

  let changedFiles: Awaited<ReturnType<StoriesGitAccess['getChangedFiles']>>;
  let repoRoot: string;
  try {
    [changedFiles, repoRoot] = await Promise.all([git.getChangedFiles(), git.getRepoRoot()]);
  } catch (error) {
    // Not a git repository, or git itself is unusable. Change detection legitimately answers
    // "no changes detected" here — the pre-toolset tool degraded the same way — so the failure
    // must not turn the whole tool into an error for the agent.
    logger.debug(`Unreachable-file detection skipped, git is unavailable: ${error}`);
    return [];
  }
  const relativeFiles = [...new Set([...changedFiles.changed, ...changedFiles.new])].filter(
    (file) => SOURCE_EXT_RE.test(file)
  );

  const unreachable: string[] = [];
  for (
    let start = 0;
    start < relativeFiles.length && unreachable.length < maxFiles;
    start += CHUNK_SIZE
  ) {
    const chunk = relativeFiles.slice(start, start + CHUNK_SIZE);
    // One batched lookup per chunk; the result is positional.
    const hits = await moduleGraph.queries.storiesForFiles.loaded({
      files: chunk.map((file) => resolvePath(repoRoot, file)),
    });
    for (const [position, file] of chunk.entries()) {
      if (unreachable.length >= maxFiles) {
        break;
      }
      if ((hits[position]?.length ?? 0) === 0) {
        unreachable.push(file);
      }
    }
  }

  return unreachable;
}

import type { StandardSchemaV1 } from '@standard-schema/spec';

/** File map used by static snapshot building. Each key represents one serialized state snapshot. */
export type StaticStore = Record<string, unknown>;

/** Generic Standard Schema constraint used across open-service definitions. */
export type AnySchema = StandardSchemaV1<unknown, unknown>;

/** Stable alias for service identifiers across definition, runtime, and registration APIs. */
export type ServiceId = string;

/**
 * Constrains a service's state to a plain object — the only shape the architecture supports.
 *
 * This is not an arbitrary restriction; two layers require it:
 *
 * 1. State is wrapped in a `deepSignal` proxy for fine-grained per-field reactivity, and `deepSignal`
 *    throws ("this object can't be observed") on primitives, `null`, and `undefined` — there are no
 *    fields to track on a scalar.
 * 2. Cross-peer sync (`applyStatePatch` in `service-sync.ts`) merges state by walking object keys;
 *    it has no notion of replacing a whole scalar, so the wire protocol only carries keyed objects.
 *
 * Arrays are technically observable by `deepSignal` but are still rejected here: `applyStatePatch`
 * replaces arrays wholesale rather than merging by key, so a *top-level* array state would silently
 * fail to sync between peers. Wrap collections in a field instead (`{ items: [...] }`).
 *
 * Authoring helpers pair this with an `extends object` bound (which rejects primitives, `null`, and
 * `undefined` while still accepting both `interface` and `type` declarations). The naked `TState` in
 * the intersection keeps it transparent to inference; only an array collapses to the branded error.
 */
export type ServiceState<TState> = TState &
  (TState extends readonly unknown[]
    ? {
        __openServiceStateError: 'Service state must be a plain object, not an array.';
      }
    : unknown);

/** Public schema shape exposed when describing a schema-backed service contract. */
export type SchemaDescriptor = AnySchema;

/** Convenience alias for declaring Standard Schema compatible input/output contracts. */
export type Schema<TInput = unknown, TOutput = TInput> = StandardSchemaV1<TInput, TOutput>;

/** Raw caller-facing value type accepted by a schema-backed operation. */
export type InferSchemaInput<TSchema extends AnySchema> = StandardSchemaV1.InferInput<TSchema>;

/** Parsed value type produced by a schema after validation. */
export type InferSchemaOutput<TSchema extends AnySchema> = StandardSchemaV1.InferOutput<TSchema>;

/**
 * Named schema maps are the core inference surface for inline open-service authoring.
 *
 * `defineService()` infers one input-schema map and one output-schema map per operation family
 * (queries and commands). Keeping those maps separate gives TypeScript a place to correlate the
 * `input` and `output` properties of each inline object before it contextually types sibling
 * callbacks like `handler`, `load`, `staticPath`, and `staticInputs`.
 */
export type OperationInputSchemas = Record<string, AnySchema>;

/**
 * Output-schema maps must stay key-aligned with their input-schema map.
 *
 * The authoring helper uses this alias instead of a plain `Record<string, AnySchema>` so each
 * operation key retains its own input/output schema pair during inference.
 */
export type MatchingOutputSchemas<TInputSchemas extends OperationInputSchemas> = {
  [TKey in keyof TInputSchemas]: AnySchema;
};

/**
 * Internal utility used to keep handler maps assignable without collapsing everything to `unknown`.
 */
type BivariantCallback<TArgs extends unknown[], TResult> = {
  bivarianceHack(...args: TArgs): TResult;
}['bivarianceHack'];

/** Runtime shape shared by all command collections after they are built. */
export type Command = Record<string, (input: unknown) => Promise<unknown>>;

/**
 * Runtime command map derived directly from the inferred command schema maps.
 *
 * Queries only need command-call typing, not the full command definition objects, so this helper
 * keeps query contexts readable while still preserving exact input/output types per command.
 */
export type CommandFunctions<
  TCommandInputSchemas extends OperationInputSchemas,
  TCommandOutputSchemas extends MatchingOutputSchemas<TCommandInputSchemas>,
> = {
  [TKey in keyof TCommandInputSchemas]: BivariantCallback<
    [input: InferSchemaInput<TCommandInputSchemas[TKey]>],
    Promise<InferSchemaOutput<TCommandOutputSchemas[TKey]>>
  >;
};

/**
 * Coarse lifecycle of a query's `load`, modeled after TanStack Query's `status`.
 *
 * - `pending` — no successful load has completed yet (and none has failed). The query may still
 *   expose `data` (the synchronous "current best" handler result), but nothing has been loaded.
 * - `error` — the most recent attempt (load rejection, or a synchronous handler / validation throw)
 *   failed. `data` keeps the last successful value, if any.
 * - `success` — a load has completed (or the query has no `load`, so there is nothing to load).
 */
export type QueryStatus = 'pending' | 'error' | 'success';

/**
 * Whether a `load` is currently running, modeled after TanStack Query's `fetchStatus` — but named
 * with our own `load` vocabulary because open-service "loads" are any slow async work (computation,
 * extraction, I/O), not specifically remote fetching.
 *
 * - `loading` — a `load` is in flight (the first load, or a reactive background re-load).
 * - `idle` — no `load` is currently running.
 */
export type LoadStatus = 'loading' | 'idle';

/**
 * The reactive state of a subscribed query: its current `data` plus the lifecycle of its `load`.
 *
 * `data` and `status` are independent. `data` is the synchronous handler result ("current best
 * effort") and holds the last successful value (or `undefined` before the first success / when a
 * handler throws), while `status`/`loadStatus`/`error` describe the asynchronous `load` lifecycle
 * tracked per subscription. A query with no `load` is `success`/`idle` from its first emission.
 *
 * `isLoading` is intentionally "any load in flight" (TanStack's `isFetching`), and
 * `isInitialLoading` is "a load is in flight and there is nothing to show yet"; the names follow our
 * `load` vocabulary rather than TanStack's `fetch`/`load` split. Unlike TanStack Query, a
 * subscription here can attach to a query whose `data` is already cached in service state, so
 * `isInitialLoading` additionally requires `data === undefined` — it never flags over cached data.
 */
export type QueryState<TData> = {
  /** Last successfully produced value; `undefined` before the first success. */
  data: TData | undefined;
  /** The failure that produced `status: 'error'`, otherwise `undefined`. */
  error: Error | undefined;
  status: QueryStatus;
  loadStatus: LoadStatus;
  /** `status === 'pending'`. */
  isPending: boolean;
  /** `status === 'success'`. */
  isSuccess: boolean;
  /** `status === 'error'`. */
  isError: boolean;
  /** `loadStatus === 'loading'` — any load in flight, foreground or background. */
  isLoading: boolean;
  /** `isPending && isLoading && data === undefined` — a first load with nothing to show yet. */
  isInitialLoading: boolean;
  /** `isLoading && !isPending` — a background re-load while data is already shown. */
  isRefreshing: boolean;
};

/**
 * Public runtime shape of a query.
 *
 * - `.get(input)` reads synchronously: it validates input, runs the handler against current state,
 *   and returns the validated result. It does **not** fire the query's `load` — it is a pure
 *   "current best effort" read. (Reads of *other* queries from inside a handler or `load` body still
 *   participate in dependency tracking, so `.loaded()` and subscriptions trigger those dependency
 *   loads; a bare consumer `.get()` does not.)
 * - `.loaded(input)` awaits the full load — this query's `load` plus every transitively read
 *   dependency — before resolving with the validated result.
 * - `.subscribe(input, callback)` invokes `callback` synchronously with the current {@link QueryState}
 *   and again whenever tracked state or the load lifecycle changes (deduped on the whole state).
 *   Subscribing is what fires the query's reactive `load`.
 *
 * There is intentionally no bare-call form: a previous `query(input)` that returned synchronously
 * *and* fired the `load` behind the scenes was removed because the implicit background load was
 * confusing. Read with `.get(input)`, await with `.loaded(input)`, observe with `.subscribe(...)`.
 *
 * Queries whose input schema resolves to `undefined` (for example `v.void()`) may be called with
 * zero arguments: `query.get()`, `query.loaded()`.
 */
type InputQuery<TInput, TOutput> = {
  get(input: TInput): TOutput;
  loaded(input: TInput): Promise<TOutput>;
  subscribe(input: TInput, callback: (state: QueryState<TOutput>) => void): () => void;
  subscribe<TSelected>(
    input: TInput,
    selector: (value: TOutput) => TSelected,
    callback: (state: QueryState<TSelected>) => void
  ): () => void;
};

/** Zero-argument overloads merged into {@link Query} when the input schema is void. */
type VoidQuery<TOutput> = {
  get(): TOutput;
  loaded(): Promise<TOutput>;
  subscribe(callback: (state: QueryState<TOutput>) => void): () => void;
  subscribe<TSelected>(
    selector: (value: TOutput) => TSelected,
    callback: (state: QueryState<TSelected>) => void
  ): () => void;
};

export type Query<TInput, TOutput> = undefined extends TInput
  ? VoidQuery<TOutput> & InputQuery<TInput, TOutput>
  : InputQuery<TInput, TOutput>;

/**
 * Runtime query map derived directly from the inferred query schema maps.
 *
 * The query counterpart to {@link CommandFunctions}: it preserves each sibling query's exact
 * input/output types on the read-only `self.queries` handle, so a handler or `load` can call
 * `self.queries.someQuery.get(input)` without manual casts. `defineService` computes this map from
 * the inferred query schema maps and threads it into the handler/load contexts as their `TQueries`;
 * the erased {@link AnyQueryFunctions} bound is used everywhere the concrete map is not known.
 */
export type QueryFunctions<
  TQueryInputSchemas extends OperationInputSchemas,
  TQueryOutputSchemas extends MatchingOutputSchemas<TQueryInputSchemas>,
> = {
  [TKey in keyof TQueryInputSchemas]: Query<
    InferSchemaInput<TQueryInputSchemas[TKey]>,
    InferSchemaOutput<TQueryOutputSchemas[TKey]>
  >;
};

/**
 * Permissive bound for a `self.queries` handle.
 *
 * Every {@link Query} — input or void — structurally satisfies {@link InputQuery} (the void
 * overloads are additive), so this is the supertype that any concrete {@link QueryFunctions} map is
 * assignable to. It is the bound (and erased default) for the `TQueries` parameter below, which lets
 * the precise per-service map flow into handler contexts while still erasing cleanly into the
 * structural `AnyQueryDefinition` storage constraint. Using `Query<unknown, unknown>` here instead
 * would wrongly demand the void zero-arg overloads from input queries.
 */
export type AnyQueryFunctions = Record<string, InputQuery<unknown, unknown>>;

/**
 * Read-only service handle exposed to query handlers.
 *
 * Query handlers are strict readers: they can read state and call sibling queries, but they cannot
 * mutate state and cannot invoke commands. Mutations belong in commands; load-side preparation
 * belongs in `load`.
 */
export type QuerySelf<TState = unknown, TQueries extends AnyQueryFunctions = AnyQueryFunctions> = {
  readonly state: TState;
  queries: TQueries;
};

/**
 * Load handle exposed to `load` functions.
 *
 * `load` may read state and queries, and may invoke declared commands to mutate state. It does
 * not receive `setState` directly — all writes must flow through commands so authors keep one
 * documented mutation surface per service.
 */
export type LoadSelf<
  TState = unknown,
  TCommandInputSchemas extends OperationInputSchemas = OperationInputSchemas,
  TCommandOutputSchemas extends MatchingOutputSchemas<TCommandInputSchemas> =
    MatchingOutputSchemas<TCommandInputSchemas>,
  TQueries extends AnyQueryFunctions = AnyQueryFunctions,
> = QuerySelf<TState, TQueries> & {
  commands: CommandFunctions<TCommandInputSchemas, TCommandOutputSchemas>;
};

/**
 * Mutable service handle exposed to command handlers.
 *
 * Commands receive both `setState` for direct state mutation and `commands` so one command can
 * delegate to another within the same service.
 */
export type CommandSelf<
  TState = unknown,
  TCommandInputSchemas extends OperationInputSchemas = OperationInputSchemas,
  TCommandOutputSchemas extends MatchingOutputSchemas<TCommandInputSchemas> =
    MatchingOutputSchemas<TCommandInputSchemas>,
  TQueries extends AnyQueryFunctions = AnyQueryFunctions,
> = LoadSelf<TState, TCommandInputSchemas, TCommandOutputSchemas, TQueries> & {
  setState(mutate: (state: TState) => void): void;
};

export type ServiceSummary = {
  id: ServiceId;
  description?: string;
  queryNames: string[];
  commandNames: string[];
};

export type OperationDescriptor = {
  name: string;
  description?: string;
  input: SchemaDescriptor;
  output: SchemaDescriptor;
  /** Present when the query declares `staticPath` at definition time. */
  staticPath?: true;
};

export type ServiceDescriptor = {
  id: ServiceId;
  description?: string;
  queries: Record<string, OperationDescriptor>;
  commands: Record<string, OperationDescriptor>;
};

/** Context passed to query handlers. */
export type QueryCtx<TState, TQueries extends AnyQueryFunctions = AnyQueryFunctions> = {
  self: QuerySelf<TState, TQueries>;
  getService: ServiceRegistryApi['getService'];
};

/** Context passed to `load` functions and static-input enumerators. */
export type LoadCtx<
  TState,
  TCommandInputSchemas extends OperationInputSchemas = OperationInputSchemas,
  TCommandOutputSchemas extends MatchingOutputSchemas<TCommandInputSchemas> =
    MatchingOutputSchemas<TCommandInputSchemas>,
  TQueries extends AnyQueryFunctions = AnyQueryFunctions,
> = {
  self: LoadSelf<TState, TCommandInputSchemas, TCommandOutputSchemas, TQueries>;
  getService: ServiceRegistryApi['getService'];
};

/** Static input enumerator stored on registered definitions; always receives load context. */
export type RegisteredStaticInputs<TState> = BivariantCallback<
  [ctx: LoadCtx<TState>],
  unknown[] | Promise<unknown[]>
>;

/** Context passed to command handlers. */
export type CommandCtx<
  TState,
  TCommandInputSchemas extends OperationInputSchemas = OperationInputSchemas,
  TCommandOutputSchemas extends MatchingOutputSchemas<TCommandInputSchemas> =
    MatchingOutputSchemas<TCommandInputSchemas>,
  TQueries extends AnyQueryFunctions = AnyQueryFunctions,
> = {
  self: CommandSelf<TState, TCommandInputSchemas, TCommandOutputSchemas, TQueries>;
  getService: ServiceRegistryApi['getService'];
};

/**
 * Declarative definition for one query.
 *
 * Queries validate caller input synchronously, run a synchronous read-only handler, and validate
 * the resolved output. The optional `load` hook is fired by subscriptions (reactively) and by
 * `.loaded()` callers (drained to completion), deduped per `(service, query, input)` while one is
 * already in flight — a bare `.get()` read never fires it.
 *
 * Queries that participate in static JSON generation declare `staticPath` at definition time.
 * `staticInputs` may also be declared here when the input list has no runtime dependencies; inputs
 * that need registry or story-index context belong in server registration instead.
 */
export type QueryDefinition<
  TState,
  TInputSchema extends AnySchema,
  TOutputSchema extends AnySchema,
  TCommandInputSchemas extends OperationInputSchemas = OperationInputSchemas,
  TCommandOutputSchemas extends MatchingOutputSchemas<TCommandInputSchemas> =
    MatchingOutputSchemas<TCommandInputSchemas>,
  TQueries extends AnyQueryFunctions = AnyQueryFunctions,
> = {
  description?: string;
  /**
   * When true, hides this query from `describeService()` output. Defaults to false. Does not disable
   * the query at runtime — callers with a service handle can still invoke it.
   */
  internal?: boolean;
  input: TInputSchema;
  output: TOutputSchema;
  /** Logical path for the serialized state snapshot, relative to this service's output folder. */
  staticPath?: BivariantCallback<[input: InferSchemaOutput<TInputSchema>], string>;
  /** Dependency-free static build inputs declared alongside the public contract. */
  staticInputs?: BivariantCallback<
    [],
    InferSchemaInput<TInputSchema>[] | Promise<InferSchemaInput<TInputSchema>[]>
  >;
  handler?: BivariantCallback<
    [input: InferSchemaOutput<TInputSchema>, ctx: QueryCtx<TState, TQueries>],
    InferSchemaInput<TOutputSchema>
  >;
  load?: BivariantCallback<
    [
      input: InferSchemaOutput<TInputSchema>,
      ctx: LoadCtx<TState, TCommandInputSchemas, TCommandOutputSchemas, TQueries>,
    ],
    void | Promise<void>
  >;
};

/**
 * Declarative definition for one command.
 *
 * Commands validate caller input, run against a mutable context, and validate the resolved output.
 */
export type CommandDefinition<
  TState,
  TInputSchema extends AnySchema,
  TOutputSchema extends AnySchema,
  TCommandInputSchemas extends OperationInputSchemas = OperationInputSchemas,
  TCommandOutputSchemas extends MatchingOutputSchemas<TCommandInputSchemas> =
    MatchingOutputSchemas<TCommandInputSchemas>,
  TQueries extends AnyQueryFunctions = AnyQueryFunctions,
> = {
  description?: string;
  /**
   * When true, hides this command from `describeService()` output. Defaults to false. Does not
   * disable the command at runtime — callers with a service handle can still invoke it.
   */
  internal?: boolean;
  input: TInputSchema;
  output: TOutputSchema;
  handler?: BivariantCallback<
    [
      input: InferSchemaOutput<TInputSchema>,
      ctx: CommandCtx<TState, TCommandInputSchemas, TCommandOutputSchemas, TQueries>,
    ],
    InferSchemaInput<TOutputSchema> | Promise<InferSchemaInput<TOutputSchema>>
  >;
};

/** Internal structural constraint used to store any query definition in a record. */
export type AnyQueryDefinition<TState> = {
  description?: string;
  internal?: boolean;
  input: AnySchema;
  output: AnySchema;
  staticPath?: BivariantCallback<[input: unknown], string>;
  staticInputs?: RegisteredStaticInputs<TState>;
  handler?: BivariantCallback<[input: unknown, ctx: QueryCtx<TState>], unknown>;
  load?: BivariantCallback<[input: unknown, ctx: LoadCtx<TState>], void | Promise<void>>;
};

/** Internal structural constraint used to store any command definition in a record. */
export type AnyCommandDefinition<TState> = {
  description?: string;
  internal?: boolean;
  input: AnySchema;
  output: AnySchema;
  handler?: BivariantCallback<
    [input: unknown, ctx: CommandCtx<TState>],
    unknown | Promise<unknown>
  >;
};

/** Named query map attached to a service definition. */
export type Queries<TState> = Record<string, AnyQueryDefinition<TState>>;
/** Named command map attached to a service definition. */
export type Commands<TState> = Record<string, AnyCommandDefinition<TState>>;

/** Top-level description of a service: identity, initial state, queries, and commands. */
export type ServiceDefinition<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
  // `TId` defaults to the wide `ServiceId`, so the common `ServiceDefinition<S, Q, C>` form is
  // unchanged. `defineService` infers it as a literal (e.g. `'core/docgen'`) so callers that key off
  // a definition's id — like the `core-service-types.ts` maps — can recover that literal.
  TId extends ServiceId = ServiceId,
> = {
  id: TId;
  description?: string;
  /**
   * When true, hides this service from `listServices()` output and requires
   * `getService(id, { internal: true })` to resolve it. Defaults to false.
   * Internal services are unstable: Storybook may break their ids, state, and operations without
   * a public semver bump. Prefer public toolsets (`defineToolset`) for MCP/CLI surfaces.
   */
  internal?: boolean;
  /**
   * Initial state for the service. Must be a plain object (not a primitive, `null`, or array) — see
   * {@link ServiceState} for why. The authoring boundary (`defineService`) enforces this; the runtime
   * type stays `TState` so already-constructed definitions flow through the registry unchanged.
   */
  initialState: TState;
  queries: TQueries;
  commands: TCommands;
};

/** Structural constraint for any service definition stored in the registry. */
export type AnyServiceDefinition = ServiceDefinition<unknown, Queries<unknown>, Commands<unknown>>;

/** Runtime service instance derived from a `ServiceDefinition`. */
export type ServiceInstance<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
> = {
  queries: {
    [TKey in keyof TQueries]: TQueries[TKey] extends {
      input: infer TInputSchema extends AnySchema;
      output: infer TOutputSchema extends AnySchema;
    }
      ? Query<InferSchemaInput<TInputSchema>, InferSchemaOutput<TOutputSchema>>
      : never;
  };
  commands: {
    [TKey in keyof TCommands]: TCommands[TKey] extends {
      input: infer TInputSchema extends AnySchema;
      output: infer TOutputSchema extends AnySchema;
    }
      ? (input: InferSchemaInput<TInputSchema>) => Promise<InferSchemaOutput<TOutputSchema>>
      : never;
  };
};

/** Runtime instance type recovered from one authored service definition. */
export type ServiceInstanceOf<TDefinition extends AnyServiceDefinition> =
  TDefinition extends ServiceDefinition<infer TState, infer TQueries, infer TCommands>
    ? ServiceInstance<TState, TQueries, TCommands>
    : never;

export type GetServiceOptions = {
  /**
   * Required when the target service is marked `internal: true`. Internal OSA surfaces are unstable
   * and may change without a semver bump — only pass this when you intentionally accept that risk.
   */
  internal?: boolean;
};

export interface ServiceRegistryApi {
  listServices(): Promise<ServiceSummary[]>;
  describeService(serviceId: ServiceId): Promise<ServiceDescriptor>;
  getService<TInstance = RuntimeService>(
    serviceId: ServiceId,
    options?: GetServiceOptions
  ): TInstance;
}

export type RuntimeService = ServiceInstance<unknown, Queries<unknown>, Commands<unknown>> &
  ServiceRegistryApi;

export type ServiceQueryRegistration<TState> = {
  /** Static build inputs that may depend on registry or other server context. */
  staticInputs?: RegisteredStaticInputs<TState>;
};

export type ServiceCommandRegistration<
  TState,
  TCommand extends AnyCommandDefinition<TState>,
> = Pick<TCommand, 'handler'>;

export type ServiceRegistrationOptions<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
> = {
  queries?: {
    [TKey in keyof TQueries]?: ServiceQueryRegistration<TState>;
  };
  commands?: {
    [TKey in keyof TCommands]?: ServiceCommandRegistration<TState, TCommands[TKey]>;
  };
};

export type ServerServiceRegistration<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
> = {
  definition: ServiceDefinition<TState, TQueries, TCommands>;
} & ServiceRegistrationOptions<TState, TQueries, TCommands>;

/** One completed static build task before it is merged into the final store map. */
export type BuildTaskResult = {
  path: string;
  state: unknown;
};

// @vitest-environment happy-dom
import { renderHook } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { clearChannel, installNoopChannel } from '../../channels/channel-slot.ts';

import { mutableRecordLookupServiceDef } from './fixtures.ts';
import { clearRegistry, registerService } from './service-registry.ts';
import { useServiceCommand } from './use-service-command.ts';

beforeEach(() => {
  installNoopChannel();
});

afterEach(() => {
  clearRegistry();
  clearChannel();
});

describe('useServiceCommand', () => {
  it('returns a callable async function', async () => {
    const service = registerService(mutableRecordLookupServiceDef);

    const { result } = renderHook(() => useServiceCommand(service, 'assignRecordField'));

    await result.current({ entryId: 'a', fieldKey: 'k', fieldValue: 'v' });

    expect(service.queries.recordFields.get({ entryId: 'a' })).toEqual({ k: 'v' });
  });

  it('returns the same function reference across re-renders', () => {
    const service = registerService(mutableRecordLookupServiceDef);

    const { result, rerender } = renderHook(() => useServiceCommand(service, 'assignRecordField'));

    const first = result.current;
    rerender();

    expect(result.current).toBe(first);
  });
});

/**
 * React hook to get a stable reference to a service command.
 *
 * Fire-and-forget: the returned async function invokes the command and returns a Promise.
 * Callers manage their own loading/error state. This keeps the hook minimal and composable
 * with any state management approach (local `useState`, `useReducer`, TanStack Query, etc.).
 *
 * The reference is stable as long as `service` and `commandName` do not change, so it is
 * safe to pass to child components or include in effect dependency arrays.
 */

import * as React from 'react';

type CommandFn<TCommands, TKey extends keyof TCommands> = TCommands[TKey] extends (
  ...args: any[]
) => any
  ? TCommands[TKey]
  : never;

/**
 * Returns a stable reference to the named service command.
 *
 * @param service - A service instance from `registerService`.
 * @param commandName - The name of the command to invoke.
 *
 * @example
 * ```tsx
 * const assignField = useServiceCommand(service, 'assignRecordField');
 *
 * return (
 *   <button onClick={() => assignField({ entryId: 'a', fieldKey: 'x', fieldValue: 'y' })}>
 *     Update
 *   </button>
 * );
 * ```
 */
export function useServiceCommand<
  // Accept any concretely-typed service: a command typed `(input: { id }) => ...` is not assignable
  // to `(input: unknown) => ...` under contravariance, so a `Pick<RuntimeService>` constraint would
  // reject every service whose command takes an object input.
  TInstance extends { commands: Record<string, (input: any) => Promise<any>> },
  TKey extends keyof TInstance['commands'] & string,
>(service: TInstance, commandName: TKey): CommandFn<TInstance['commands'], TKey> {
  return React.useMemo(
    () => service.commands[commandName] as CommandFn<TInstance['commands'], TKey>,
    [service, commandName]
  );
}

// @vitest-environment happy-dom
import { renderHook, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { clearChannel, installNoopChannel } from '../../channels/channel-slot.ts';

import {
  awaitedPreloadValueServiceDef,
  mutableRecordLookupServiceDef,
  undefinedOutputQueryServiceDef,
} from './fixtures.ts';
import { clearRegistry, registerService } from './service-registry.ts';
import type { Query, QueryState } from './types.ts';
import { useServiceQuery } from './use-service-query.ts';

beforeEach(() => {
  installNoopChannel();
});

afterEach(() => {
  clearRegistry();
  clearChannel();
});

describe('useServiceQuery', () => {
  it('returns the initial synchronous query result as data', () => {
    const service = registerService(mutableRecordLookupServiceDef);

    const { result } = renderHook(() =>
      useServiceQuery(service.queries.recordFields, { entryId: 'a' })
    );

    expect(result.current.data).toBeNull();
    expect(result.current.isError).toBe(false);
  });

  it('shows pending with the synchronous get() data while a load-backed query loads', async () => {
    const service = registerService(awaitedPreloadValueServiceDef);

    const { result } = renderHook(() =>
      useServiceQuery(service.queries.preloadedValue, { entryId: 'a' })
    );

    // A load-backed query stays `pending` until its load settles. `data` is the synchronous
    // `get()` value (null here, before the load has populated state).
    expect(result.current.status).toBe('pending');
    expect(result.current.isPending).toBe(true);
    expect(result.current.data).toBeNull();

    await waitFor(() => expect(result.current.data).toBe('preloaded'));
  });

  it('re-renders when the query result changes after a command', async () => {
    const service = registerService(mutableRecordLookupServiceDef);

    const { result } = renderHook(() =>
      useServiceQuery(service.queries.recordFields, { entryId: 'a' })
    );

    expect(result.current.data).toBeNull();

    await service.commands.assignRecordField({
      entryId: 'a',
      fieldKey: 'color',
      fieldValue: 'red',
    });

    await waitFor(() => {
      expect(result.current.data).toEqual({ color: 'red' });
    });
  });

  it('does not re-render for an unrelated entry', async () => {
    const service = registerService(mutableRecordLookupServiceDef);
    let renderCount = 0;

    renderHook(() => {
      renderCount++;
      return useServiceQuery(service.queries.recordFields, { entryId: 'a' });
    });

    const countAfterMount = renderCount;

    await service.commands.assignRecordField({
      entryId: 'b',
      fieldKey: 'other',
      fieldValue: 'value',
    });

    // Wait a tick to let any spurious re-renders fire.
    await new Promise<void>((resolve) => setTimeout(resolve, 20));

    // No re-render because the subscribed key ('a') was not affected.
    expect(renderCount).toBe(countAfterMount);
  });

  it('updates when input changes', async () => {
    const service = registerService(mutableRecordLookupServiceDef);

    await service.commands.assignRecordField({
      entryId: 'a',
      fieldKey: 'k',
      fieldValue: 'v',
    });

    let currentEntryId = 'b';
    const { result, rerender } = renderHook(() =>
      useServiceQuery(service.queries.recordFields, { entryId: currentEntryId })
    );

    expect(result.current.data).toBeNull();

    currentEntryId = 'a';
    rerender();

    expect(result.current.data).toEqual({ k: 'v' });
  });

  it('accumulates incremental updates', async () => {
    const service = registerService(mutableRecordLookupServiceDef);

    const { result } = renderHook(() =>
      useServiceQuery(service.queries.recordFields, { entryId: 'a' })
    );

    await service.commands.assignRecordField({ entryId: 'a', fieldKey: 'x', fieldValue: '1' });

    await waitFor(() => {
      expect(result.current.data).toEqual({ x: '1' });
    });

    await service.commands.assignRecordField({ entryId: 'a', fieldKey: 'y', fieldValue: '2' });

    await waitFor(() => {
      expect(result.current.data).toEqual({ x: '1', y: '2' });
    });
  });

  it('treats an undefined query output as initialised, not as a recompute sentinel', () => {
    const service = registerService(undefinedOutputQueryServiceDef);
    // Re-subscription happens only when the lazy-init subscription key changes. If `undefined`
    // output were mistaken for "uninitialised", the key would be rebuilt on every render and the
    // hook would resubscribe each time.
    const subscribeSpy = vi.spyOn(service.queries.nothing, 'subscribe');

    const { result, rerender } = renderHook(() => useServiceQuery(service.queries.nothing));

    expect(result.current.data).toBeUndefined();

    const subscribeCallsAfterMount = subscribeSpy.mock.calls.length;

    rerender();
    rerender();

    expect(result.current.data).toBeUndefined();
    expect(subscribeSpy.mock.calls.length).toBe(subscribeCallsAfterMount);
  });

  it('re-renders on every emission (no hook-level dedup) and reflects the latest state', async () => {
    const subscribers: Array<(queryState: QueryState<{ k: string }>) => void> = [];
    const successState = (data: { k: string }): QueryState<{ k: string }> => ({
      data,
      error: undefined,
      status: 'success',
      loadStatus: 'idle',
      isPending: false,
      isSuccess: true,
      isError: false,
      isLoading: false,
      isInitialLoading: false,
      isRefreshing: false,
    });
    const recordFields = {
      get: vi.fn(() => ({ k: 'v' })),
      subscribe: vi.fn(
        (
          _input: { entryId: string },
          callback: (queryState: QueryState<{ k: string }>) => void
        ) => {
          subscribers.push(callback);
          return () => {};
        }
      ),
    } as unknown as Query<{ entryId: string }, { k: string }>;

    let renderCount = 0;
    const { result } = renderHook(() => {
      renderCount++;
      return useServiceQuery(recordFields, { entryId: 'a' });
    });

    // The first render is the synthetic `pending` seed built from `get()`.
    expect(result.current.isPending).toBe(true);
    expect(result.current.data).toEqual({ k: 'v' });

    await waitFor(() => expect(subscribers).toHaveLength(1));

    // The first real emission transitions the seed (`pending`) to `success`, so it re-renders.
    const countBeforeSuccess = renderCount;
    subscribers[0](successState({ k: 'v' }));
    await waitFor(() => expect(result.current.isSuccess).toBe(true));
    expect(renderCount).toBe(countBeforeSuccess + 1);

    // The hook does not dedup: even a new-reference, deeply-equal emission re-renders. (The runtime
    // dedups its own emissions; the hook deliberately trusts that rather than re-checking equality,
    // which previously masked mutations of deeply-nested state.)
    const countAfterSuccess = renderCount;
    subscribers[0](successState({ k: 'v' }));
    await waitFor(() => expect(renderCount).toBe(countAfterSuccess + 1));

    // A genuinely different state is reflected too.
    subscribers[0](successState({ k: 'changed' }));
    await waitFor(() => expect(result.current.data).toEqual({ k: 'changed' }));
    expect(renderCount).toBe(countAfterSuccess + 2);
  });
});

/**
 * React hook to subscribe to a service query with fine-grained reactivity.
 *
 * Backed by React's `useSyncExternalStore`, so it integrates correctly with React 18+ concurrent
 * features. Manager-only: that hook does not exist before React 18, and the preview must keep
 * supporting React 16/17, so preview docs blocks use the shim-based `useQuerySubscription` instead.
 *
 * Returns a {@link QueryState}: the current `data` plus the `load` lifecycle (`status`,
 * `loadStatus`, `error`, and the derived booleans). Re-renders whenever the subscribed query emits
 * (the runtime already dedupes deeply-equal emissions, so the hook does not). Object inputs are
 * compared with deep equality when deciding whether to re-subscribe, so inline literals at the call
 * site are safe; selectors are compared by reference, so memoize them (`useCallback` / module
 * scope) to avoid re-subscribing every render.
 */

import * as React from 'react';

import { isEqual } from 'es-toolkit/predicate';

import { seedQueryState } from './query-state.ts';
import type { Query, QueryState } from './types.ts';

/**
 * Subscribe to a service query and receive reactive {@link QueryState} updates in a React component.
 *
 * Pass the query directly (e.g. `myService.queries.thing`) so its input/output types infer per
 * query. The service must exist: if it may be absent (e.g. behind a feature flag), guard at a parent
 * and conditionally render the component that calls this hook.
 *
 * A void-input query needs no input argument. As soon as a selector is involved the input is
 * positional, so a void-input query passes `undefined` explicitly:
 * `useServiceQuery(query, undefined, selector)`.
 *
 * @example
 * ```tsx
 * const { data, isInitialLoading, isError } = useServiceQuery(recordService.queries.recordFields, {
 *   entryId: 'a',
 * });
 * ```
 */
export function useServiceQuery<TOutput>(query: Query<void, TOutput>): QueryState<TOutput>;
export function useServiceQuery<TInput, TOutput>(
  query: Query<TInput, TOutput>,
  input: TInput
): QueryState<TOutput>;
export function useServiceQuery<TInput, TOutput, TSelected>(
  query: Query<TInput, TOutput>,
  input: TInput,
  selector: (value: TOutput) => TSelected
): QueryState<TSelected>;
export function useServiceQuery(
  query: Query<unknown, unknown>,
  input?: unknown,
  selector?: (value: unknown) => unknown
): QueryState<unknown> {
  // The first render is seeded synchronously: `useSyncExternalStore` reads `getSnapshot` during
  // render but only runs `subscribe` in a post-paint passive effect, so a snapshot must already
  // exist. We read the current data with `query.get(input)` (a pure read that fires no load) and
  // wrap it in a synthetic `pending` state; the real lifecycle arrives moments later from the
  // subscription's first emission. The seed is recomputed only when the subscription key changes:
  // `query`/`selector` by reference and `input` by deep equality (so inline object literals are
  // safe). `subscriptionKeyRef` is null until the first run — the init sentinel, not the snapshot.
  const subscriptionKeyRef = React.useRef<{
    query: Query<unknown, unknown>;
    input: unknown;
    selector: ((value: unknown) => unknown) | undefined;
  } | null>(null);
  const snapshotRef = React.useRef<QueryState<unknown> | undefined>(undefined);

  if (
    subscriptionKeyRef.current === null ||
    subscriptionKeyRef.current.query !== query ||
    !isEqual(subscriptionKeyRef.current.input, input) ||
    subscriptionKeyRef.current.selector !== selector
  ) {
    subscriptionKeyRef.current = { query, input, selector };
    snapshotRef.current = selector
      ? seedQueryState(query, input, selector)
      : seedQueryState(query, input);
  }

  // Stable for deep-equal inputs — only replaced when the query, input value, or selector changes.
  const subscriptionKey = subscriptionKeyRef.current!;

  const subscribe = React.useCallback(
    (listener: () => void): (() => void) => {
      const { query: q, input: i, selector: s } = subscriptionKey;
      const onQueryState = (queryState: QueryState<unknown>) => {
        snapshotRef.current = queryState;
        listener();
      };
      return s ? q.subscribe(i, s, onQueryState) : q.subscribe(i, onQueryState);
    },
    [subscriptionKey]
  );

  // React may call getSnapshot multiple times during render/bailout checks, so it must be a pure
  // ref read rather than recomputing the seed (which would re-run the handler) on every call.
  const getSnapshot = React.useCallback((): QueryState<unknown> => {
    return snapshotRef.current as QueryState<unknown>;
  }, []);

  // Only runs in manager, so React 18 is available.
  return React.useSyncExternalStore(subscribe, getSnapshot);
}
